def link_inheritance(ctx: Ctx):
    children: dict[str, list[str]] = collections.defaultdict(list)
    for t in ctx.types:
        if t.get("extends"):
            children[t["extends"].lower()].append(t["name"])
    for t in ctx.types:
        chain = []
        seen = set()
        cur = t.get("extends", "")
        while cur and cur.lower() not in seen:
            seen.add(cur.lower())
            chain.append(cur)
            bt = ctx.type_by_name.get(cur.lower())
            cur = bt["extends"] if bt else ""
        t["bases"] = chain
        own = {m["name"].lower() for m in t["methods"]}
        inh = []
        for b in chain:
            bt = ctx.type_by_name.get(b.lower())
            if not bt:
                continue
            for m in bt["methods"]:
                if m["name"].lower() not in own and m["kind"] not in ("CONSTRUCTOR", "DESTRUCTOR"):
                    inh.append(f"{bt['name']}.{m['name']}")
                    own.add(m["name"].lower())
        t["inherited"] = inh
        t["children"] = sorted(children.get(t["name"].lower(), [])) if t["name"] else []


