def qname(r: dict) -> str:
    return (r["container"] + "." if r["container"] else "") + r["name"]


def fmt_params(r: dict) -> str:
    return ", ".join(p["raw"] for p in r["params"])


def routine_lines(r: dict, ctx: Ctx) -> list[str]:
    by_id = ctx.by_id  # type: ignore[attr-defined]
    L: list[str] = []
    qn = qname(r)
    if r["kind"] == "MODÜL":
        L.append(f"MODÜL GÖVDESİ  [{r['id']}]  satır {r['line']}-{r['end_line']}  (üst düzey çalıştırılan deyimler; karmaşıklık {r['cc']})")
    elif r["proto"]:
        ext = f"  DLL: {r['lib']}!{r['alias'] or r['name']}" if r["lib"] else ""
        L.append(f"{r['kind']} {qn}  [{r['id']}]  satır {r['line']}  [ön tanım]{ext}")
    else:
        L.append(f"{r['kind']} {qn}  [{r['id']}]  satır {r['line']}-{r['end_line']}  ({r['end_line'] - r['line'] + 1} satır, karmaşıklık {r['cc']})")
    if r["kind"] != "MODÜL":
        L.append(f"   imza    : {r['kind'].lower()} {qn}({fmt_params(r)})" + (f" As {r['ret']}" if r["ret"] else ""))
    amac = r.get("amac") or ""
    L.append(f"   amaç    : {amac if amac else '(henüz açıklanmadı)'}" + (f"  [{r['amac_kaynak']}]" if amac else ""))
    pw = set(r["p_write"])
    if r["params"]:
        parts = []
        for p in r["params"]:
            mode = p["mode"] or "ByVal(varsayılan)"
            io = "okunur+yazılır (çıkış)" if p["name"].lower() in pw else "okunur"
            parts.append(f"{p['name']}: {p['type'] or '?'} ({mode}{', dizi' if p['array'] else ''}, {io})")
        L.append("   girdi   : " + "; ".join(parts))
    else:
        L.append("   girdi   : (parametre yok)")
    outs = []
    if r["ret"]:
        outs.append(f"döndürür {r['ret']}")
    elif r["kind"] in ("FUNCTION", "PROPERTY", "OPERATOR") and not r["proto"]:
        outs.append("döndürür (tür belirtilmemiş)")
    if pw:
        outs.append("çıkış parametreleri: " + ", ".join(sorted(pw)))
    if r["g_write"]:
        outs.append("yazdığı global: " + ", ".join(r["g_write"][:10]))
    if r["fields_write"]:
        outs.append("yazdığı THIS alanları: " + ", ".join(r["fields_write"][:10]))
    L.append("   çıktı   : " + (" | ".join(outs) if outs else "(değer döndürmez, dışarıya yazmaz)"))
    if r["locals"]:
        L.append("   yerel   : " + "; ".join(
            f"{l['name']}{'(' + l['dims'] + ')' if l['dims'] else ''}: {l['type'] or '?'}" for l in r["locals"][:14])
            + (f" … (+{len(r['locals']) - 14})" if len(r["locals"]) > 14 else ""))
    if r["g_read"] or r["g_write"]:
        rd = [g for g in r["g_read"] if g not in r["g_write"]]
        L.append(f"   global  : okur [{', '.join(rd[:10])}]  okur+yazar [{', '.join(sorted(set(r['g_read']) & set(r['g_write']))[:10])}]  yalnız yazar [{', '.join(sorted(set(r['g_write']) - set(r['g_read']))[:10])}]")
    if r["fields_read"]:
        L.append("   THIS    : alan kullanımı " + ", ".join(r["fields_read"][:12]))
    if r["c_used"]:
        L.append("   sabit   : " + ", ".join(r["c_used"][:14]) + (f" … (+{len(r['c_used']) - 14})" if len(r["c_used"]) > 14 else ""))
    if r["types_used"]:
        L.append("   tipler  : " + ", ".join(r["types_used"][:10]))
    if r["callees"]:
        items = sorted(r["callees"].items(), key=lambda kv: -kv[1])
        L.append("   çağırır : " + ", ".join(f"{qname(by_id[k])}({v})" if v > 1 else qname(by_id[k]) for k, v in items[:12])
                 + (f" … (+{len(items) - 12})" if len(items) > 12 else ""))
    if r["dll"]:
        for d in r["dll"][:4]:
            L.append(f"   DLL     : {d['lib']}!{d['fn']}({', '.join(a['type'] for a in d['args'])}) -> {d['ret']} [{d['conv']}]")
    if r["ext_calls"]:
        L.append("   dış API : " + ", ".join(sorted(r["ext_calls"])[:8]))
    if r.get("amb_methods"):
        L.append("   belirsiz metot çağrıları (alıcı tipi bilinmiyor): " + ", ".join(sorted(r["amb_methods"])[:8]))
    if r["callers"]:
        items = sorted(r["callers"].items(), key=lambda kv: -kv[1])
        L.append(f"   çağrılır: {len(items)} rutinden: " + ", ".join(qname(by_id[k]) for k, _ in items[:6]) + (" …" if len(items) > 6 else ""))
    for tb in ctx.tables_of.get(r["id"], []):  # type: ignore[attr-defined]
        L.append(f"   tablo   : {tb['id']} {tb['kind']} {tb['subject']} ({tb['case_count']} durum; {tb['tur']})")
    return L


def type_lines(t: dict, ctx: Ctx) -> list[str]:
    L = []
    ext = f"  (miras: {', '.join([t['extends']] + [b for b in t['bases'][1:]])})" if t.get("extends") else ""
    imp = f"  (uygular: {', '.join(t['implements'])})" if t.get("implements") else ""
    L.append(f"{t['kind']} {(t['ns'] + '.' if t['ns'] else '')}{t['name'] or '(adsız)'}  [{t['id']}]  satır {t['line']}-{t['end_line']}{ext}{imp}")
    cm = squash(" ".join(t["doc"]) or t["trail"], 220)
    L.append(f"   amaç/yorum: {cm if cm else '(kaynakta yorum yok)'}")
    if t["alias_of"]:
        L.append(f"   takma ad  : {t['alias_of']}")
    for f in t["fields"]:
        L.append(f"   alan    {f['name']}{'(' + f['dims'] + ')' if f['dims'] else ''} : {f['type'] or '?'}"
                 + (f" = {f['init']}" if f["init"] else "") + (f"  [{f['access']}]" if f["access"] else "")
                 + (f"   ' {f['cmt']}" if f["cmt"] else ""))
    if t["members"]:
        mem = ", ".join(m["name"] + (f"={m['value']}" if m["value"] else "") for m in t["members"][:50])
        L.append(f"   üyeler ({len(t['members'])}): {mem}" + (" …" if len(t["members"]) > 50 else ""))
    for m in t["methods"]:
        L.append(f"   metot   {m['kind']} {m['name']}({fmt_params(m)})" + (f" As {m['ret']}" if m["ret"] else "") + f"  [{m['id']}]" + ("  [ön tanım]" if m["proto"] else ""))
    if t.get("inherited"):
        L.append("   devraldığı metotlar: " + ", ".join(t["inherited"][:16]))
    if t.get("children"):
        L.append("   alt tipler: " + ", ".join(t["children"][:12]))
    if t["used_by"]:
        ub = list(dict.fromkeys(t["used_by"]))
        L.append(f"   kullanan rutin: {len(ub)} (örn. " + ", ".join(qname(ctx.by_id[x]) for x in ub[:5]) + ")")  # type: ignore[attr-defined]
    return L


def var_lines(v: dict, ctx: Ctx) -> list[str]:
    if v["scope"] == "CONST":
        return [f"  CONST {(v['ns'] + '.' if v['ns'] else '')}{v['name']}" + (f" As {v['type']}" if v["type"] else "")
                + (f" = {v['init']}" if v["init"] else "") + (f"   ' {v['cmt']}" if v["cmt"] else "")]
    rd, wr = sorted(v["readers"]), sorted(v["writers"])
    names = lambda ids: ", ".join(qname(ctx.by_id[i]) for i in ids[:4]) + (" …" if len(ids) > 4 else "")  # type: ignore[attr-defined]
    return [f"  {v['scope']} {v['kind']} {v['name']}{'(' + v['dims'] + ')' if v['dims'] else ''} : {v['type'] or '?'}"
            + (f" = {v['init']}" if v["init"] else "") + (f"   ' {v['cmt']}" if v["cmt"] else ""),
            f"      okuyan {len(rd)}: {names(rd)}   yazan {len(wr)}: {names(wr)}" if (rd or wr) else "      (hiçbir rutin kullanmıyor / modül düzeyinde kullanılıyor)"]


def module_text(fm, ctx: Ctx, layer: dict, cycle_of: dict, rev: dict) -> list[str]:
    L = ["=" * 100, f"MODÜL: {fm.rel}", "=" * 100]
    ozet = ctx.mod_ozet.get(fm.rel, {})  # type: ignore[attr-defined]
    cyc = f"döngüsel bağımlılık grubu #{cycle_of[fm.rel]}" if fm.rel in cycle_of else "döngü yok"
    nr = len([r for r in fm.routines if not r["proto"]])
    L.append(f"satır: {fm.lines}   katman: {layer.get(fm.rel, 0)}   {cyc}   tanımlı rutin: {nr}   tip: {len(fm.types)}")
    if ozet.get("ozet"):
        L.append(f"özet : {squash(ozet['ozet'], 700)}  [{ozet.get('source', '?')}]")
    if ozet.get("rol"):
        L.append(f"rol  : {squash(ozet['rol'], 220)}")
    if fm.header:
        L.append("başlık yorumu: " + squash(" ".join(fm.header), 400))
    incs = [i.get("resolved") or ("(çözülemedi) " + i["target"]) for i in fm.includes]
    if incs:
        L.append(f"include ettiği ({len(incs)}): " + ", ".join(incs[:14]) + (" …" if len(incs) > 14 else ""))
    inby = sorted(rev.get(fm.rel, ()))
    if inby:
        L.append(f"include eden ({len(inby)}): " + ", ".join(inby[:10]) + (" …" if len(inby) > 10 else ""))
    if fm.namespaces:
        L.append("ad alanları: " + ", ".join(sorted(fm.namespaces)))
    if fm.macros:
        L.append(f"makrolar ({len(fm.macros)}): " + ", ".join(m["name"] for m in fm.macros[:20]) + (" …" if len(fm.macros) > 20 else ""))
    if fm.types:
        L += ["", f"--- TİPLER ({len(fm.types)}) ---"]
        for t in fm.types:
            L += type_lines(t, ctx)
            L.append("")
    if fm.vars:
        L += [f"--- GLOBAL DEĞİŞKENLER / SABİTLER ({len(fm.vars)}) ---"]
        for v in fm.vars:
            L += var_lines(v, ctx)
        L.append("")
    rts = [r for r in ctx.routines if r["file"] == fm.rel] if False else ctx.routines_of.get(fm.rel, [])  # type: ignore[attr-defined]
    if rts:
        L += [f"--- RUTİNLER ({len(rts)}) ---"]
        for r in rts:
            L += routine_lines(r, ctx)
            L.append("")
    return L


def tables_text(ctx: Ctx, min_cases: int = 3) -> list[str]:
    L = ["KARAR TABLOLARI (SELECT CASE ve IF/ELSEIF zincirleri)", "=" * 100,
         f"toplam: {len(ctx.tables)} (okunur listede en az {min_cases} durumlu olanlar)", ""]  # type: ignore[attr-defined]
    for t in ctx.tables:  # type: ignore[attr-defined]
        if t["case_count"] < min_cases:
            continue
        L.append(f"[{t['id']}] {t['kind']} {t['subject']}  —  {t['file']}:{t['line']}-{t['end_line']}  | rutin: {t['owner']} | {t['case_count']} durum{', ELSE var' if t['has_else'] else ''} | tür: {t['tur']}")
        am = t.get("amac", "")
        L.append(f"   amaç: {am if am else '(henüz açıklanmadı)'}")
        for c in t["cases"][:40]:
            L.append(f"   {c['label']}  ->  {c['action']}")
        if len(t["cases"]) > 40:
            L.append(f"   … (+{len(t['cases']) - 40} durum daha; tamamı veri/tablolar.jsonl içinde)")
        L.append("")
    return L


