def cross_check(ctx: Ctx, files: list[Path]) -> list[str]:
    L = ["ÇAPRAZ DOĞRULAMA", "=" * 100]
    mine_defs = {(r["file"], r["name"].lower()) for r in ctx.routines if r["kind"] != "MODÜL" and not r["proto"]}
    mine_all = {(r["file"], r["name"].lower()) for r in ctx.routines if r["kind"] != "MODÜL"}
    L.append(f"Bu analizci: {len(mine_defs)} tanımlı rutin adı (dosya,ad), {len(mine_all)} ön tanım dahil")
    # --- rutinler.tsv ---
    tsv = V4 / "ajan_paketi" / "rutinler.tsv"
    if tsv.exists():
        tdefs, tall = set(), set()
        with tsv.open("r", encoding="utf-8", errors="replace", newline="") as f:
            rd = csv.reader(f, delimiter="\t", quoting=csv.QUOTE_NONE)
            head = next(rd, [])
            for row in rd:
                if len(row) < 8:
                    continue
                d = dict(zip(head, row))
                tall.add((d["dosya"], d["ad"].lower()))
                if not d["tur"].endswith("*"):
                    tdefs.add((d["dosya"], d["ad"].lower()))
        scope = {r["file"] for r in ctx.routines} | {fm.rel for fm in ctx.models}  # type: ignore[attr-defined]
        tdefs = {x for x in tdefs if x[0] in scope}
        both = mine_defs & tdefs
        L += ["", "[1] ajan_paketi/rutinler.tsv (Codex harita çıkarıcısı) ile — tanımlı rutinler, aynı dosya kümesinde",
              f"    tsv: {len(tdefs)}   ortak: {len(both)}   yalnız bu analizcide: {len(mine_defs - tdefs)}   yalnız tsv'de: {len(tdefs - mine_defs)}",
              f"    örtüşme: tsv'nin %{100 * len(both) / max(1, len(tdefs)):.1f}'i bulundu; bu analizcinin %{100 * len(both) / max(1, len(mine_defs)):.1f}'i tsv'de var",
              "    (tsv, harita üretildiği andaki kaynaktan; aradaki farkın bir kısmı kaynak değişikliğinden olabilir)"]
        for tag, s in (("yalnız bu analizcide", sorted(mine_defs - tdefs)), ("yalnız tsv'de", sorted(tdefs - mine_defs))):
            L.append(f"    {tag} (ilk 12): " + "; ".join(f"{a.split('/')[-1]}:{b}" for a, b in s[:12]))
    # --- ctags ---
    import shutil
    exe = shutil.which("ctags")
    if exe:
        try:
            inp = "\n".join(str(p) for p in files)
            pr = subprocess.run([exe, "--langmap=Basic:.fbs.bas.bi.inc.fb.uxmh.uxb", "--languages=Basic", "--output-format=json",
                                 "--fields=+n", "-f", "-", "-L", "-"], input=inp, capture_output=True, text=True,
                                encoding="utf-8", errors="replace", timeout=600)
            cset = set()
            for line in pr.stdout.splitlines():
                try:
                    d = json.loads(line)
                except ValueError:
                    continue
                if d.get("_type") == "tag" and d.get("kind") in ("function", "subroutine", "method"):
                    try:
                        rel = Path(d["path"]).resolve().relative_to(WORKSPACE).as_posix()
                    except Exception:
                        continue
                    cset.add((rel, d["name"].lower()))
            both = mine_all & cset
            L += ["", "[2] Universal Ctags 6.1 (bağımsız, üçüncü taraf ayrıştırıcı) ile — function/sub adları (ön tanımlar dahil)",
                  f"    ctags: {len(cset)}   ortak: {len(both)}   yalnız bu analizcide: {len(mine_all - cset)}   yalnız ctags'te: {len(cset - mine_all)}",
                  f"    örtüşme: ctags'in %{100 * len(both) / max(1, len(cset)):.1f}'i bulundu; bu analizcinin %{100 * len(both) / max(1, len(mine_all)):.1f}'i ctags'te var"]
            L.append("    yalnız ctags'te (ilk 12): " + "; ".join(f"{a.split('/')[-1]}:{b}" for a, b in sorted(cset - mine_all)[:12]))
            L.append("    yalnız bu analizcide (ilk 12): " + "; ".join(f"{a.split('/')[-1]}:{b}" for a, b in sorted(mine_all - cset)[:12]))
        except Exception as exc:  # noqa: BLE001
            L += ["", f"[2] ctags çalıştırılamadı: {exc}"]
    else:
        L += ["", "[2] ctags bulunamadı; atlandı."]
    # --- blok dengesi ---
    diag = [(fm.rel, d) for fm in ctx.models for d in fm.diag]  # type: ignore[attr-defined]
    L += ["", f"[3] Blok dengesi (rutin/tip için END eksik ya da fazla): {len(diag)} uyarı"]
    for rel, d in diag[:25]:
        L.append(f"    {rel}: {d}")
    unres = sum(len(v) for v in ctx.mod_unresolved.values())  # type: ignore[attr-defined]
    L += ["", f"[4] Çözülemeyen include sayısı: {unres}  (sistem/dış başlıklar olabilir)"]
    for m, lst in list(ctx.mod_unresolved.items())[:10]:  # type: ignore[attr-defined]
        L.append(f"    {m}: {', '.join(lst[:4])}")
    return L


