def jsonable(o):
    if isinstance(o, set):
        return sorted(o)
    if isinstance(o, collections.Counter):
        return {f"{k[0]}:{k[1]}": v for k, v in o.items()}
    raise TypeError(type(o))


def write_jsonl(path: Path, rows):
    with path.open("w", encoding="utf-8", newline="\n") as f:
        for r in rows:
            f.write(json.dumps(r, ensure_ascii=False, default=jsonable) + "\n")


def write_tsv(path: Path, head: list[str], rows):
    with path.open("w", encoding="utf-8", newline="\n") as f:
        f.write("\t".join(head) + "\n")
        for r in rows:
            f.write("\t".join(str(x).replace("\t", " ").replace("\n", " ") for x in r) + "\n")


def routine_row(r: dict) -> dict:
    d = {k: v for k, v in r.items() if k not in ("body", "calls_raw", "callers", "callees")}
    d["callees"] = r["callees"]
    d["callers"] = r["callers"]
    return d


def write_outputs(ctx: Ctx, out: Path, log) -> dict:
    (out / "veri").mkdir(parents=True, exist_ok=True)
    (out / "moduller").mkdir(parents=True, exist_ok=True)
    by_id = ctx.by_id  # type: ignore[attr-defined]
    models = ctx.models  # type: ignore[attr-defined]
    edges, rev, layer, cycles = ctx.mod_edges, ctx.mod_rev, ctx.mod_layer, ctx.mod_cycles  # type: ignore[attr-defined]
    cycle_of = {m: i + 1 for i, c in enumerate(cycles) for m in c}
    ctx.routines_of = collections.defaultdict(list)  # type: ignore[attr-defined]
    for r in ctx.routines:
        ctx.routines_of[r["file"]].append(r)  # type: ignore[attr-defined]
    ctx.tables_of = collections.defaultdict(list)  # type: ignore[attr-defined]
    for t in ctx.tables:  # type: ignore[attr-defined]
        if t.get("owner_id"):
            ctx.tables_of[t["owner_id"]].append(t)  # type: ignore[attr-defined]
    # --- veri dosyaları ---
    write_jsonl(out / "veri" / "rutinler.jsonl", (routine_row(r) for r in ctx.routines))
    write_jsonl(out / "veri" / "tipler.jsonl", ({**{k: v for k, v in t.items() if k != "methods"},
                                                  "methods": [m["id"] for m in t["methods"]]} for t in ctx.types))
    write_jsonl(out / "veri" / "globaller.jsonl", (v for v in ctx.vars))
    write_jsonl(out / "veri" / "tablolar.jsonl", ctx.tables)  # type: ignore[attr-defined]
    mods = []
    for fm in models:
        mods.append({"file": fm.rel, "lines": fm.lines, "layer": layer.get(fm.rel, 0), "cycle_group": cycle_of.get(fm.rel),
                     "header": fm.header, "namespaces": sorted(fm.namespaces),
                     "includes": [i.get("resolved") or i["target"] for i in fm.includes],
                     "unresolved_includes": [i["target"] for i in fm.includes if not i.get("resolved")],
                     "included_by": sorted(rev.get(fm.rel, ())),
                     "routine_count": len([r for r in fm.routines if not r["proto"]]),
                     "proto_count": len([r for r in fm.routines if r["proto"]]),
                     "type_count": len(fm.types), "macro_count": len(fm.macros), "diag": fm.diag,
                     "ozet": ctx.mod_ozet.get(fm.rel, {}).get("ozet", ""), "rol": ctx.mod_ozet.get(fm.rel, {}).get("rol", "")})  # type: ignore[attr-defined]
    write_jsonl(out / "veri" / "moduller.jsonl", mods)
    write_tsv(out / "veri" / "iliski_cagri.tsv", ["cagiran_id", "cagiran", "cagiran_dosya", "cagrilan_id", "cagrilan", "cagrilan_dosya", "sayi"],
              ((r["id"], qname(r), r["file"], cid, qname(by_id[cid]), by_id[cid]["file"], n)
               for r in ctx.routines for cid, n in sorted(r["callees"].items())))
    write_tsv(out / "veri" / "iliski_include.tsv", ["dosya", "include_ettigi"],
              ((a, b) for a, bs in sorted(edges.items()) for b in sorted(bs)))
    write_tsv(out / "veri" / "iliski_tip.tsv", ["rutin_id", "rutin", "tip"],
              ((r["id"], qname(r), t) for r in ctx.routines for t in r["types_used"]))
    write_tsv(out / "veri" / "iliski_global.tsv", ["rutin_id", "rutin", "global", "erisim"],
              ((r["id"], qname(r), g, ("RW" if g in r["g_write"] and g in r["g_read"] else ("W" if g in r["g_write"] else "R")))
               for r in ctx.routines for g in sorted(set(r["g_read"]) | set(r["g_write"]))))
    write_tsv(out / "veri" / "iliski_sabit.tsv", ["rutin_id", "rutin", "sabit_ya_da_enum_uyesi"],
              ((r["id"], qname(r), c) for r in ctx.routines for c in r["c_used"]))
    write_tsv(out / "veri" / "iliski_miras.tsv", ["tip", "taban", "tur"],
              [(t["name"], t["extends"], t["kind"]) for t in ctx.types if t.get("extends")]
              + [(t["name"], i, "IMPLEMENTS") for t in ctx.types for i in t.get("implements", [])])
    write_tsv(out / "veri" / "dll_cagrilari.tsv", ["rutin_id", "rutin", "dosya", "kutuphane", "islev", "donus", "cagri_bicimi", "arguman_tipleri"],
              ((r["id"], qname(r), r["file"], d["lib"], d["fn"], d["ret"], d["conv"], ",".join(a["type"] for a in d["args"]))
               for r in ctx.routines for d in r["dll"]))
    write_tsv(out / "veri" / "sabitler.tsv", ["ad", "deger", "tip", "tur", "dosya", "satir", "ad_alani"],
              [(v["name"], v["init"], v["type"], "CONST", v["file"], v["line"], v["ns"]) for v in ctx.vars if v["scope"] == "CONST"]
              + [(m["name"], m["value"], t["name"], "ENUM_UYESI", t["file"], m["line"], t["ns"]) for t in ctx.types if t["kind"] == "ENUM" for m in t["members"]])
    write_tsv(out / "veri" / "makrolar.tsv", ["tur", "ad", "arguman", "govde", "dosya", "satir"],
              [(m["kind"], m["name"], m["args"], m["body"], m["file"], m["line"]) for fm in models for m in fm.macros])
    # --- modül metinleri ---
    order = sorted(models, key=lambda fm: (layer.get(fm.rel, 0), fm.rel))
    texts: dict[str, list[str]] = {}
    for fm in order:
        texts[fm.rel] = module_text(fm, ctx, layer, cycle_of, rev)
        flat = re.sub(r'[\\/:*?"<>|]', "__", fm.rel) + ".txt"
        (out / "moduller" / flat).write_text("\n".join(texts[fm.rel]) + "\n", encoding="utf-8", newline="\n")
    toc = ["uXBasic KOD ANALİZİ — TEK DOSYA", f"üretim: {datetime.now().isoformat(timespec='seconds')}",
           "Sıra: bağımlılık katmanına göre (katman 0 = hiçbir şeyi include etmeyen, en alttaki modüller).",
           f"modül sayısı: {len(order)}", "", "İÇİNDEKİLER (katman | dosya | rutin sayısı)", "-" * 100]
    for fm in order:
        toc.append(f"{layer.get(fm.rel, 0):3d} | {fm.rel} | {len([r for r in fm.routines if not r['proto']])}")
    toc.append("")
    with (out / "UXB_KOD_ANALIZ_TEK_DOSYA.txt").open("w", encoding="utf-8", newline="\n") as f:
        f.write("\n".join(toc) + "\n")
        for fm in order:
            f.write("\n".join(texts[fm.rel]) + "\n")
    (out / "tablolar.txt").write_text("\n".join(tables_text(ctx)) + "\n", encoding="utf-8", newline="\n")
    # DOT
    with (out / "veri" / "iliski_modul.dot").open("w", encoding="utf-8", newline="\n") as f:
        f.write("digraph moduller {\n  rankdir=LR; node [shape=box,fontsize=9];\n")
        for a, bs in sorted(edges.items()):
            for b in sorted(bs):
                f.write(f'  "{a.rsplit("/", 1)[-1]}" -> "{b.rsplit("/", 1)[-1]}";\n')
        f.write("}\n")
    return {"modul_metin": len(order)}


def network_md(ctx: Ctx) -> list[str]:
    by_id = ctx.by_id  # type: ignore[attr-defined]
    edges, rev, layer, cycles = ctx.mod_edges, ctx.mod_rev, ctx.mod_layer, ctx.mod_cycles  # type: ignore[attr-defined]
    L = ["# İlişki ağları — özet", ""]
    L.append("## 1. Döngüsel include grupları (derleme sırasını kilitleyebilir)")
    if not cycles:
        L.append("Yok.")
    for i, c in enumerate(sorted(cycles, key=len, reverse=True), 1):
        L.append(f"- Grup #{i} ({len(c)} dosya): " + ", ".join(x.rsplit("/", 1)[-1] for x in c[:12]) + (" …" if len(c) > 12 else ""))
    L += ["", "## 2. Katman dağılımı (0 = en alt, hiçbir şeyi include etmez)"]
    dist = collections.Counter(layer.values())
    L.append("| katman | dosya |")
    L.append("|---|---|")
    for k in sorted(dist):
        L.append(f"| {k} | {dist[k]} |")
    L += ["", "## 3. En çok include edilen dosyalar"]
    for m, s in sorted(rev.items(), key=lambda kv: -len(kv[1]))[:15]:
        L.append(f"- {m} ← {len(s)} dosya")
    L += ["", "## 4. En çok include eden dosyalar"]
    for m, s in sorted(edges.items(), key=lambda kv: -len(kv[1]))[:15]:
        L.append(f"- {m} → {len(s)} dosya")
    L += ["", "## 5. En çok çağrılan rutinler (çağıran rutin sayısı)"]
    for r in sorted(ctx.routines, key=lambda r: -len(r["callers"]))[:25]:
        if r["callers"]:
            L.append(f"- {qname(r)} [{r['id']}] ({r['file']}) ← {len(r['callers'])} rutin")
    L += ["", "## 6. En çok rutin çağıran rutinler"]
    for r in sorted(ctx.routines, key=lambda r: -len(r["callees"]))[:20]:
        if r["callees"]:
            L.append(f"- {qname(r)} [{r['id']}] ({r['file']}) → {len(r['callees'])} rutin")
    L += ["", "## 7. En karmaşık rutinler (karmaşıklık = 1 + dallanma sayısı)"]
    for r in sorted((r for r in ctx.routines if not r["proto"]), key=lambda r: -r["cc"])[:20]:
        L.append(f"- {qname(r)} [{r['id']}] ({r['file']}:{r['line']}) karmaşıklık {r['cc']}, {r['end_line'] - r['line'] + 1} satır")
    L += ["", "## 8. En çok yazılan global değişkenler"]
    for v in sorted((v for v in ctx.vars if v["scope"] == "GLOBAL"), key=lambda v: -len(v["writers"]))[:15]:
        if v["writers"]:
            L.append(f"- {v['name']} ({v['file']}:{v['line']}) yazan {len(v['writers'])}, okuyan {len(v['readers'])}")
    L += ["", "## 9. En çok kullanılan tipler"]
    for t in sorted(ctx.types, key=lambda t: -len(set(t["used_by"])))[:15]:
        if t["used_by"]:
            L.append(f"- {t['kind']} {t['name']} ({t['file']}) ← {len(set(t['used_by']))} rutin")
    L += ["", "## 10. Miras ağacı"]
    roots = [t for t in ctx.types if t.get("children") and not t.get("extends")]
    if not roots:
        L.append("Hiçbir TYPE/CLASS `Extends` kullanmıyor (kaynak kökleri içinde).")
    for t in roots:
        L.append(f"- {t['name']} → {', '.join(t['children'])}")
    dl = collections.Counter(d["lib"] for r in ctx.routines for d in r["dll"])
    L += ["", "## 11. DLL çağrıları (CALL(DLL,…)) kütüphane başına"]
    for lib, n in dl.most_common(30):
        L.append(f"- {lib}: {n} çağrı")
    if not dl:
        L.append("Yok.")
    return L


def summary_md(ctx: Ctx, out: Path, stats: dict) -> str:
    rts = [r for r in ctx.routines if r["kind"] != "MODÜL"]
    defs = [r for r in rts if not r["proto"]]
    kinds = collections.Counter(r["kind"] for r in defs)
    tk = collections.Counter(t["kind"] for t in ctx.types)
    src = collections.Counter((r.get("amac_kaynak") or "yok").split("(")[0] for r in defs)
    L = ["# uXBasic kod analizi — özet", "",
         f"- üretim: {datetime.now().isoformat(timespec='seconds')}  (süre: {stats['sure']:.0f} sn)",
         f"- çözümlenen dosya: {len(ctx.models)}  ({sum(fm.lines for fm in ctx.models):,} satır)",  # type: ignore[attr-defined]
         f"- tanımlı rutin: {len(defs)}  " + ", ".join(f"{k}={v}" for k, v in sorted(kinds.items())) + f";  ön tanım (Declare): {len(rts) - len(defs)}",
         f"- tip: {len(ctx.types)}  " + ", ".join(f"{k}={v}" for k, v in sorted(tk.items())),
         f"- global değişken: {len([v for v in ctx.vars if v['scope'] == 'GLOBAL'])};  modül düzeyi sabit: {len([v for v in ctx.vars if v['scope'] == 'CONST'])};  makro: {sum(len(fm.macros) for fm in ctx.models)}",  # type: ignore[attr-defined]
         f"- karar tablosu: {len(ctx.tables)}  (SELECT CASE {len([t for t in ctx.tables if t['kind'] == 'SELECT_CASE'])}, IF zinciri {len([t for t in ctx.tables if t['kind'] == 'IF_ZINCIRI'])})",  # type: ignore[attr-defined]
         f"- çağrı ilişkisi (kenar): {sum(len(r['callees']) for r in ctx.routines)};  include ilişkisi: {sum(len(v) for v in ctx.mod_edges.values())};  döngüsel include grubu: {len(ctx.mod_cycles)}",  # type: ignore[attr-defined]
         f"- amaç kapsamı (tanımlı rutinlerde): " + ", ".join(f"{k}={v}" for k, v in src.most_common()),
         "",
         "## Dosyalar (bu klasörde)",
         "| dosya | ne işe yarar |", "|---|---|",
         "| `UXB_KOD_ANALIZ_TEK_DOSYA.txt` | tüm modüller tek metin dosyasında (bağımlılık sırasıyla) |",
         "| `moduller/*.txt` | her modülün ayrı metni (aynı biçim) |",
         "| `tablolar.txt` | SELECT CASE / IF zinciri karar tabloları, okunur liste |",
         "| `iliski_agi.md` | modül, çağrı, tip, global ilişki ağlarının özeti (döngüler, katmanlar, en çok kullanılanlar) |",
         "| `saglik.txt` | çözümleme sağlığı + ctags ve rutinler.tsv ile çapraz doğrulama |",
         "| `veri/rutinler.jsonl` | her rutin: imza, girdi, çıktı, yerel, çağırdıkları, global okuma/yazma, karmaşıklık |",
         "| `veri/tipler.jsonl` | TYPE/UNION/ENUM/CLASS: alanlar, üyeler, metotlar, miras, kullananlar |",
         "| `veri/globaller.jsonl`, `sabitler.tsv`, `makrolar.tsv` | değişkenler, sabitler, makrolar |",
         "| `veri/tablolar.jsonl` | karar tablolarının tüm durumları |",
         "| `veri/iliski_*.tsv`, `iliski_modul.dot` | ağ kenarları (çağrı, include, tip, global, sabit, miras) |",
         "",
         "## Sınırlar (dürüst not)",
         "- Satır tabanlı çözümleme; tam derleyici ayrıştırıcısı değildir. Sağlık raporundaki sayılar bağımsız araçlarla karşılaştırılmıştır.",
         "- Çağrılar ada göre çözülür; aynı adlı birden çok rutin varsa tüm adaylar bağlanır. Alıcı tipi bilinmeyen `nesne.metot()` çağrıları `belirsiz` listelenir.",
         "- ByRef argümanla dolaylı yazma, işaretçi takma adları ve FreeBASIC'te alan adının örtük `this` ile kullanımı izlenmez.",
         "- Koşullu derleme (`#if`) dallarının hepsi çözümlenir. `amaç` metinleri model taslağıdır; `[yorum]` kaynaktaki yorumdur.",
         "- Karar tablolarının `amaç` alanı ayrı bir adımda (model ile) doldurulur; boşsa 'henüz açıklanmadı' yazar."]
    return "\n".join(L) + "\n"


