class Kota:
    """Dakikalık istek + dakikalık girdi token'ı + günlük/çalıştırma başına istek sınırı; günlük sayaç diskte."""

    def __init__(self, saglayici: str, rpm: float, rpd: int, tpm: int, max_istek: int) -> None:
        self.state = V4 / "logs" / f"kota_{saglayici}.json"
        self.min_gap = 60.0 / max(0.1, rpm)
        self.rpd, self.tpm, self.max_istek = rpd, tpm, max_istek
        self.run_count, self.last = 0, 0.0
        self.sent: deque[tuple[float, int]] = deque()
        self.day = time.strftime("%Y-%m-%d")
        self.count = 0
        try:
            st = json.loads(self.state.read_text(encoding="utf-8"))
            if st.get("gun") == self.day:
                self.count = int(st.get("istek", 0))
        except (OSError, ValueError):
            pass

    def bekle(self, chars: int) -> str:
        if self.rpd and self.count >= self.rpd:
            return "GUNLUK_KOTA"
        if self.max_istek and self.run_count >= self.max_istek:
            return "CALISMA_SINIRI"
        tokens = int(chars / 3.2) + 1
        while True:
            now = time.time()
            while self.sent and now - self.sent[0][0] > 60:
                self.sent.popleft()
            used = sum(t for _, t in self.sent)
            if not self.sent or not self.tpm or used + tokens <= self.tpm:
                break
            time.sleep(max(1.0, 60 - (now - self.sent[0][0]) + 0.5))
        gap = time.time() - self.last
        if gap < self.min_gap:
            time.sleep(self.min_gap - gap)
        self.last = time.time()
        self.sent.append((self.last, tokens))
        return ""

    def say(self) -> None:
        self.count += 1
        self.run_count += 1
        self.state.parent.mkdir(parents=True, exist_ok=True)
        self.state.write_text(json.dumps({"gun": self.day, "istek": self.count}), encoding="utf-8")


class ModelHata(Exception):
    """kind: KOTA (günlük sınır), SINIR (çalıştırma sınırı), KALICI (anahtar/model — sağlayıcı değiştir), GECICI."""

    def __init__(self, kind: str, msg: str) -> None:
        super().__init__(msg)
        self.kind = kind


# ------------------------------------------------------------------ sağlayıcı istemcisi
def gemini_semasi(schema: dict) -> dict:
    s = copy.deepcopy(schema)

    def walk(n: dict) -> dict:
        n.pop("additionalProperties", None)
        if "type" in n:
            n["type"] = n["type"].upper()
        for v in (n.get("properties") or {}).values():
            walk(v)
        if isinstance(n.get("items"), dict):
            walk(n["items"])
        return n

    return walk(s)


def http_json(url: str, body: dict, headers: dict, timeout: int = 600) -> dict:
    req = urllib.request.Request(url, data=json.dumps(body).encode("utf-8"),
                                 headers={"Content-Type": "application/json", **headers})
    with urllib.request.urlopen(req, timeout=timeout) as r:
        return json.load(r)


class Istemci:
    def __init__(self, saglayici: str, cfg: dict[str, str], model: str, kota: Kota) -> None:
        self.ad, self.cfg, self.model, self.kota = saglayici, cfg, model, kota
        self.key = cfg.get(SAGLAYICILAR[saglayici][0], "")
        self._claude = None
        self.yuk_path = V4 / "logs" / f"yuklemeler_{saglayici}.json"
        try:
            self.yuklemeler = json.loads(self.yuk_path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            self.yuklemeler = {}

    # ---- dosya yükleme (bir kere) ----
    def yukle(self, parca: dict) -> str | None:
        """Paket parçasını bir kere yükler; kimliğini döndürür. Desteklemeyen sağlayıcıda None (metin gider)."""
        if not (self.ad.startswith("gemini") or self.ad == "claude"):
            return None
        rec = self.yuklemeler.get(parca["sha"])
        if rec and (self.ad == "claude" or time.time() - rec.get("t", 0) < YUKLEME_OMRU_SN):
            return rec["id"]
        data = Path(parca["parca"]).read_bytes()
        if self.ad.startswith("gemini"):
            start = urllib.request.Request(
                "https://generativelanguage.googleapis.com/upload/v1beta/files",
                data=json.dumps({"file": {"display_name": parca["ad"]}}).encode("utf-8"),
                headers={"x-goog-api-key": self.key, "X-Goog-Upload-Protocol": "resumable",
                         "X-Goog-Upload-Command": "start", "X-Goog-Upload-Header-Content-Length": str(len(data)),
                         "X-Goog-Upload-Header-Content-Type": "text/plain", "Content-Type": "application/json"})
            with urllib.request.urlopen(start, timeout=120) as r:
                up_url = r.headers.get("x-goog-upload-url")
            if not up_url:
                raise ModelHata("GECICI", "Gemini yükleme adresi alınamadı")
            put = urllib.request.Request(up_url, data=data, headers={
                "X-Goog-Upload-Offset": "0", "X-Goog-Upload-Command": "upload, finalize",
                "Content-Length": str(len(data))})
            with urllib.request.urlopen(put, timeout=600) as r:
                fid = json.load(r)["file"]["uri"]
        else:
            self._claude_sdk()
            up = self._claude.files.upload(file=(parca["ad"], data, "text/plain"))
            fid = up.id
        self.yuklemeler[parca["sha"]] = {"id": fid, "t": time.time(), "ad": parca["ad"]}
        self.yuk_path.parent.mkdir(parents=True, exist_ok=True)

