def ayarlari_oku() -> dict[str, str]:
    """Anahtar dosyasını (KEY=DEĞER satırları, # yorum) okur; ortam değişkenleri dosyanın önüne geçer."""
    cfg: dict[str, str] = {}
    if ANAHTAR_DOSYASI.exists():
        for ln in ANAHTAR_DOSYASI.read_text(encoding="utf-8-sig").splitlines():
            s = ln.strip()
            if not s or s.startswith("#") or "=" not in s:
                continue
            k, v = s.split("=", 1)
            v = v.strip().strip('"').strip("'")
            if v:
                cfg[k.strip()] = v
    for k, v in os.environ.items():
        if v and (k.endswith("_API_KEY") or k.startswith("UXB_") or k.endswith("_BASE_URL")):
            cfg[k] = v
    return cfg


