    def _http_sor(self, system: str, user: str, schema: dict, max_tokens: int, dosya_id: str | None) -> str:
        if self.ad.startswith("gemini"):
            parts = []
            if dosya_id:
                parts.append({"file_data": {"mime_type": "text/plain", "file_uri": dosya_id}})
            parts.append({"text": user})
            data = http_json(
                f"https://generativelanguage.googleapis.com/v1beta/models/{self.model}:generateContent",
                {"systemInstruction": {"parts": [{"text": system}]},
                 "contents": [{"role": "user", "parts": parts}],
                 "generationConfig": {"temperature": 0.2, "maxOutputTokens": max_tokens,
                                      "responseMimeType": "application/json",
                                      "responseSchema": gemini_semasi(schema)}},
                {"x-goog-api-key": self.key})
            cands = data.get("candidates") or []
            if not cands:
                raise ModelHata("GECICI", "BOS_CEVAP: " + json.dumps(data.get("promptFeedback", {}))[:200])
            return "".join(p.get("text", "") for p in cands[0].get("content", {}).get("parts") or [])
        if self.ad == "chatgpt":
            base = self.cfg.get("OPENAI_BASE_URL", "https://api.openai.com/v1").rstrip("/")
            data = http_json(
                base + "/chat/completions",
                {"model": self.model, "max_completion_tokens": max_tokens,
                 "messages": [{"role": "system", "content": system}, {"role": "user", "content": user}],
                 "response_format": {"type": "json_schema",
                                     "json_schema": {"name": "harita", "schema": schema, "strict": True}}},
                {"Authorization": f"Bearer {self.key}"})
            return data["choices"][0]["message"]["content"] or ""
        if self.ad == "kimi":
            base = self.cfg.get("MOONSHOT_BASE_URL", "https://api.moonshot.ai/v1").rstrip("/")
            sys_full = system + "\nCevabı YALNIZ şu JSON şemasına uyan tek bir JSON nesnesi olarak ver:\n" + json.dumps(schema, ensure_ascii=False)
            data = http_json(
                base + "/chat/completions",
                # Kimi K2.7 Code / K3 düşünmeyi kendileri yönetir; sıcaklık gibi örnekleme ayarları gönderilmez.
                {"model": self.model, "max_tokens": max_tokens,
                 "messages": [{"role": "system", "content": sys_full}, {"role": "user", "content": user}],
                 "response_format": {"type": "json_object"}},
                {"Authorization": f"Bearer {self.key}"})
            return data["choices"][0]["message"]["content"] or ""
        raise ModelHata("KALICI", f"bilinmeyen sağlayıcı {self.ad}")

    def _claude_sdk(self):
        try:
            import anthropic  # resmi Anthropic Python SDK'sı
        except ImportError:
            raise ModelHata("KALICI", "Claude için resmi paket kurulu değil: python -m pip install anthropic")
        if self._claude is None:
            self._claude = anthropic.Anthropic(api_key=self.key, max_retries=5)
        return anthropic

    def _claude_sor(self, system: str, user: str, schema: dict, max_tokens: int, dosya_id: str | None) -> object:
        anthropic = self._claude_sdk()
        content: list[dict] = []
        if dosya_id:
            content.append({"type": "document", "source": {"type": "file", "file_id": dosya_id}})
        content.append({"type": "text", "text": user})
        kwargs = {
            "model": self.model,
            "max_tokens": max_tokens,
            "system": system,
            "messages": [{"role": "user", "content": content}],
            "output_config": {"effort": self.cfg.get("UXB_CLAUDE_EFFORT", "low"),
                              "format": {"type": "json_schema", "schema": schema}},
        }
        try:
            if self.model.startswith(("claude-opus-5", "claude-fable-5")):
                resp = self._claude.beta.messages.create(
                    betas=["server-side-fallback-2026-07-01"], fallbacks="default", **kwargs)
            else:
                resp = self._claude.messages.create(**kwargs)
        except anthropic.AuthenticationError:
            self.kota.say()
            raise ModelHata("KALICI", "ANAHTAR (Claude): ANTHROPIC_API_KEY geçersiz")
        except anthropic.PermissionDeniedError as e:
            self.kota.say()
            raise ModelHata("KALICI", f"İZİN/BAKİYE (Claude): {e.message}")
        except anthropic.NotFoundError:
            self.kota.say()
            raise ModelHata("KALICI", f"MODEL (Claude): '{self.model}' bulunamadı")
        except anthropic.BadRequestError as e:
            self.kota.say()
            kind = "KALICI" if "credit" in e.message.lower() else "GECICI"
            raise ModelHata(kind, f"ISTEK (Claude): {e.message}")
        except anthropic.RateLimitError as e:
            self.kota.say()
            raise ModelHata("GECICI", f"HIZ SINIRI (Claude, SDK yeniden denemeleri bitti): {e.message}")
        except anthropic.APIStatusError as e:
            self.kota.say()
            raise ModelHata("GECICI", f"HTTP {e.status_code} (Claude): {e.message}")
        except anthropic.APIConnectionError as e:
            raise ModelHata("GECICI", f"AG (Claude): {e}")
        self.kota.say()
        if resp.stop_reason == "refusal":
            raise ModelHata("GECICI", "RED (Claude): istek güvenlik gerekçesiyle reddedildi")
        text = next((b.text for b in resp.content if b.type == "text"), "")
        try:
            return json.loads(text)
        except json.JSONDecodeError as e:
            raise ModelHata("GECICI", f"CEVAP_COZULEMEDI (Claude, stop_reason={resp.stop_reason}): {e}")


