#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Token yönetimi — günlük/toplam tüketim, kota kontrol, fallback sırası"""

import os
import json
from pathlib import Path
from datetime import datetime

try:
    from dotenv import load_dotenv
except ImportError:
    load_dotenv = lambda x: None

# .env oku
env_file = Path.home() / '.uxb' / 'api_anahtarlari.env'
if env_file.exists():
    load_dotenv(str(env_file))

class TokenManager:
    def __init__(self):
        self.quotas = {
            'groq': {'rpm': None, 'rpd': None, 'cost': 0},
            'gemini': {'rpm': int(os.getenv('UXB_GEMINI_RPM', 8)), 'rpd': int(os.getenv('UXB_GEMINI_RPD', 240)), 'cost': 0},
            'gemini2': {'rpm': 8, 'rpd': 240, 'cost': 0},
            'kimi': {'rpm': int(os.getenv('UXB_KIMI_RPM', 10)), 'rpd': int(os.getenv('UXB_KIMI_RPD', 100)), 'cost': 0},
            'chatgpt': {'rpm': int(os.getenv('UXB_CHATGPT_RPM', 20)), 'rpd': int(os.getenv('UXB_CHATGPT_RPD', 100)), 'cost': 0.002},
            'claude': {'rpm': 20, 'rpd': 100, 'cost': 0.003},
        }
        self.usage = {}
        self.load()

    def load(self):
        """Kullanım dosyasını oku"""
        usage_file = Path.home() / '.uxb' / 'token_usage.json'
        if usage_file.exists():
            self.usage = json.loads(usage_file.read_text())

    def save(self):
        """Kullanımı kaydet"""
        usage_file = Path.home() / '.uxb' / 'token_usage.json'
        usage_file.parent.mkdir(parents=True, exist_ok=True)
        usage_file.write_text(json.dumps(self.usage, indent=2))

    def can_send(self, llm: str, tokens: int) -> bool:
        """Bu LLM'ye gönder mi?"""
        if llm not in self.quotas or self.quotas[llm]['rpd'] is None:
            return True

        today = datetime.now().strftime('%Y-%m-%d')
        if llm not in self.usage:
            self.usage[llm] = {'today': 0, 'total': 0}

        used = self.usage[llm].get('today', 0)
        quota = self.quotas[llm]['rpd']
        return used + tokens <= quota

    def log(self, llm: str, tokens: int):
        """Kullanımı kaydet"""
        today = datetime.now().strftime('%Y-%m-%d')
        if llm not in self.usage:
            self.usage[llm] = {'today': 0, 'total': 0, 'last_reset': today}

        # Gün değiştiyse sıfırla
        if self.usage[llm].get('last_reset') != today:
            self.usage[llm]['today'] = 0
            self.usage[llm]['last_reset'] = today

        self.usage[llm]['today'] += tokens
        self.usage[llm]['total'] += tokens
        self.save()

    def status(self):
        """Durum göster"""
        print(f"Token Durum — {datetime.now().strftime('%Y-%m-%d %H:%M')}\n")
        for llm, quota in self.quotas.items():
            if llm not in self.usage:
                used = 0
            else:
                used = self.usage[llm].get('today', 0)

            if quota['rpd']:
                pct = (used / quota['rpd']) * 100
                print(f"  {llm:10} {used:6}/{quota['rpd']} ({pct:5.1f}%)")
            else:
                print(f"  {llm:10} {used:6}/∞ (ücretsiz)")

if __name__ == '__main__':
    import argparse
    parser = argparse.ArgumentParser()
    parser.add_argument('--status', action='store_true')
    parser.add_argument('--log', type=str, help='llm:tokens')
    parser.add_argument('--can-send', type=str, help='llm:tokens')
    parser.add_argument('--export-csv', type=str)
    args = parser.parse_args()

    tm = TokenManager()

    if args.status:
        tm.status()
    elif args.log:
        llm, tokens = args.log.split(':')
        tm.log(llm, int(tokens))
        print(f"✓ {llm} {tokens} token kayıt")
    elif args.can_send:
        llm, tokens = args.can_send.split(':')
        if tm.can_send(llm, int(tokens)):
            print(f"✓ {llm} {tokens} token gönder")
        else:
            print(f"✗ {llm} kota aşıldı")
    elif args.export_csv:
        with open(args.export_csv, 'w') as f:
            f.write("LLM,Bugün,Toplam,Limit\n")
            for llm in tm.quotas:
                used = tm.usage.get(llm, {}).get('today', 0)
                total = tm.usage.get(llm, {}).get('total', 0)
                limit = tm.quotas[llm]['rpd'] or '∞'
                f.write(f"{llm},{used},{total},{limit}\n")
        print(f"✓ {args.export_csv}")
    else:
        tm.status()

