# --------------------------------------------------------------------------------------------------
# 10b. C / C++ kütüphane kodları (runtime_ext, native) — ctags ile; uXBasic CALL(DLL,...) çağrılarına bağlanır
# --------------------------------------------------------------------------------------------------
C_EXTS = {".c", ".cpp", ".cc", ".h", ".hh", ".hpp"}
C_ROOTS = ["uxb/runtime_ext", "uxb/native"]


def c_cpp_analiz(ctx: Ctx, out: Path) -> dict:
    import shutil
    exe = shutil.which("ctags")
    if not exe:
        return {"durum": "ctags bulunamadı; C/C++ analizi atlandı"}
    files: list[Path] = []
    for r in C_ROOTS:
        base = WORKSPACE / r
        if not base.exists():
            continue
        for p in sorted(base.rglob("*")):
            if not p.is_file() or p.suffix.lower() not in C_EXTS:
                continue
            if {x.lower() for x in p.relative_to(base).parts[:-1]} & SKIP_DIRS:
                continue
            try:
                if p.stat().st_size > MAX_FILE_BYTES:
                    continue
            except OSError:
                continue
            files.append(p)
    if not files:
        return {"durum": "C/C++ dosyası yok"}
    pr = subprocess.run([exe, "--sort=no", "--languages=C,C++", "--kinds-C=+p", "--kinds-C++=+p", "--output-format=json",
                         "--fields=+neKSsatzi", "-f", "-", "-L", "-"], input="\n".join(str(p) for p in files),
                        capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=900)
    recs: list[dict] = []
    for line in pr.stdout.splitlines():
        try:
            d = json.loads(line)
        except ValueError:
            continue
        if d.get("_type") != "tag":
            continue
        try:
            rel = Path(d["path"]).resolve().relative_to(WORKSPACE).as_posix()
        except Exception:  # noqa: BLE001
            continue
        recs.append({"ad": d["name"], "tur": d.get("kind", ""), "dosya": rel, "satir": d.get("line", 0), "bitis": d.get("end", 0),
                     "imza": d.get("signature", ""), "donus": (d.get("typeref") or "").replace("typename:", ""),
                     "kapsam": d.get("scope", ""), "kapsam_turu": d.get("scopeKind", ""), "erisim": d.get("access", ""),
                     "miras": d.get("inherits", "")})
    write_jsonl(out / "veri" / "c_cpp.jsonl", recs)
    by_file: dict[str, list[dict]] = collections.defaultdict(list)
    for r in recs:
        by_file[r["dosya"]].append(r)
    kinds = collections.Counter(r["tur"] for r in recs)
    L = ["C / C++ KÜTÜPHANE KODLARI (runtime_ext, native) — ctags ile; işlev imzası, yapı alanları, sınıf ve miras", "=" * 100,
         f"dosya: {len(by_file)}   etiket: {len(recs)}   " + ", ".join(f"{k}={v}" for k, v in kinds.most_common(10)),
         "Not: üçüncü taraf/vendor başlıkları (örn. uxwasmrt/wabt) bu listede ayrı dosyalar olarak yer alır; çağrı ağı ve girdi/çıktı çözümlemesi yalnız .fbs/.bas kaynaklar için yapılır.", ""]
    for rel in sorted(by_file):
        rs = by_file[rel]
        fn = [r for r in rs if r["tur"] == "function" and r["kapsam_turu"] not in ("function",)]
        pt = [r for r in rs if r["tur"] == "prototype"]
        st = [r for r in rs if r["tur"] in ("struct", "union", "class")]
        L.append(f"## {rel}   (işlev {len(fn)}, ön tanım {len(pt)}, yapı/sınıf {len(st)}, makro {sum(1 for r in rs if r['tur'] == 'macro')})")
        for s in st:
            mem = [m for m in rs if m["tur"] == "member" and m["kapsam"] == s["ad"]]
            L.append(f"   {s['tur'].upper()} {s['ad']}" + (f" : {s['miras']}" if s["miras"] else "") + f"  [satır {s['satir']}]"
                     + (" alanlar: " + "; ".join(f"{m['ad']}: {m['donus'] or '?'}" for m in mem[:20]) + (" …" if len(mem) > 20 else "") if mem else ""))
        for r in fn:
            L.append(f"   FUNCTION {(r['kapsam'] + '::') if r['kapsam'] else ''}{r['ad']}{r['imza'] or '()'}" + (f" -> {r['donus']}" if r["donus"] else "")
                     + f"  [satır {r['satir']}{('-' + str(r['bitis'])) if r['bitis'] else ''}]")
        if pt:
            L.append("   ön tanımlar: " + ", ".join(p["ad"] for p in pt[:25]) + (" …" if len(pt) > 25 else ""))
        en = [r for r in rs if r["tur"] == "enum"]
        for e in en:
            ms = [m["ad"] for m in rs if m["tur"] == "enumerator" and m["kapsam"] == e["ad"]]
            L.append(f"   ENUM {e['ad']} ({len(ms)} üye): " + ", ".join(ms[:20]) + (" …" if len(ms) > 20 else ""))
        td = [r["ad"] for r in rs if r["tur"] == "typedef"]
        if td:
            L.append("   typedef: " + ", ".join(td[:20]) + (" …" if len(td) > 20 else ""))
        L.append("")
    (out / "C_CPP_KUTUPHANE_KODLARI.txt").write_text("\n".join(L) + "\n", encoding="utf-8", newline="\n")
    # uXBasic sarmalayıcı -> DLL işlevi -> C kaynağı
    cdefs: dict[str, list[dict]] = collections.defaultdict(list)
    for r in recs:
        if r["tur"] == "function" and r["dosya"].lower().endswith((".c", ".cpp", ".cc")):
            cdefs[r["ad"].lower()].append(r)
    rows = []
    eslesen = toplam = 0
    for r in ctx.routines:
        for d in r["dll"]:
            toplam += 1
            hits = cdefs.get(d["fn"].lower(), [])
            eslesen += bool(hits)
            h = hits[0] if hits else None
            rows.append((r["id"], qname(r), r["file"], d["lib"], d["fn"], h["dosya"] if h else "", h["satir"] if h else "", (h["imza"] if h else "")))
    write_tsv(out / "veri" / "iliski_uxb_c.tsv", ["uxb_rutin_id", "uxb_rutin", "uxb_dosya", "dll", "dll_islevi", "c_dosya", "c_satir", "c_imza"], rows)
    return {"durum": "tamam", "dosya": len(by_file), "etiket": len(recs), "islev": kinds.get("function", 0), "yapi": kinds.get("struct", 0),
            "sinif": kinds.get("class", 0), "dll_cagri": toplam, "dll_c_eslesen": eslesen}


# --------------------------------------------------------------------------------------------------
# 11. Ana akış
# --------------------------------------------------------------------------------------------------

