h2 { font-size: 1.15rem; margin: 2.2rem 0 .7rem; padding-bottom: .35rem; border-bottom: 1px solid var(--line); text-wrap: balance; }
p { margin: .6rem 0; max-width: 70ch; }
ul { padding-left: 1.2rem; margin: .6rem 0; max-width: 75ch; }
li { margin: .25rem 0; }
code { font-family: var(--font-mono); font-size: .86em; background: var(--code-bg); padding: .08em .35em; border-radius: 4px; }
pre { background: var(--code-bg); border: 1px solid var(--line); border-radius: 6px; padding: .8rem 1rem; margin: .5rem 0; font-size: .85rem; line-height: 1.5; }
pre code { background: none; padding: 0; font-size: inherit; }
.scroll { overflow-x: auto; max-width: 100%; margin: .6rem 0; }
table { border-collapse: collapse; width: 100%; font-size: .9rem; }
th, td { text-align: left; vertical-align: top; padding: .5rem .7rem; border-bottom: 1px solid var(--line); }
th { font-size: .78rem; text-transform: uppercase; letter-spacing: .05em; color: var(--muted); background: var(--panel); position: sticky; left: 0; }
td:first-child { min-width: 9rem; }
.ok, .warn, .mute { display: inline-block; padding: .05rem .5rem; border-radius: 999px; font-size: .84rem; }
.ok { background: var(--ok-bg); color: var(--ok-fg); } .warn { background: var(--warn-bg); color: var(--warn-fg); } .mute { background: var(--mute-bg); color: var(--mute-fg); }
.callout { background: var(--call-bg); border: 1px solid var(--call-line); border-radius: 8px; padding: .8rem 1rem; max-width: 70ch; }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
