# ------------------------------------------------------------------ ek (tip / global değişken / karar tablosu amaçları)
# Kaynak: tek dosya klasörünün kod_analiz\veri\ek_oge.jsonl dosyası (Moduller\KodAnalizor.py üretir; paketleyici31.py -K).
# Önbellek: ajan_paketi\ek_amac_onbellek.jsonl (yalnız ekleme; kaynak değişirse yalnız değişen öğe yeniden sorulur).
EK_OGE = WORKSPACE / "uxb" / "tekdosyaklsoru" / "kod_analiz" / "veri" / "ek_oge.jsonl"
EK_CACHE = PKG / "ek_amac_onbellek.jsonl"
EK_PARTI_KARAKTER, EK_PARTI_OGE = 45000, 30
EK_SCHEMA = {
    "type": "object",
    "properties": {"sonuclar": {"type": "array", "items": {"type": "object", "properties": {
        "no": {"type": "integer"}, "amac": {"type": "string"}}, "required": ["no", "amac"], "additionalProperties": False}}},
    "required": ["sonuclar"], "additionalProperties": False,
}
EK_SISTEM = GENEL_BAGLAM + (
    " Görevin: sana numaralı öğeler verilir. [TİP] bir veri yapısıdır (TYPE/UNION/ENUM/CLASS), [GLOBAL DEĞİŞKEN] bir "
    "global değişkendir, [KARAR TABLOSU] bir SELECT CASE ya da IF/ELSEIF zinciridir. Her öğe için derleyicide NE İŞE "
    "YARADIĞINI tek, en çok iki Türkçe cümleyle yaz: ne tutar, hangi girdiyi hangi çıktıya/eyleme eşler, kimin için. "
    "Yalnız verilen metinden çıkarılabilen şeyi yaz; kısaltmaları açma; 'Bu tip…', 'Bu tablo…' gibi girişler kullanma, "
    "doğrudan söyle. Emin değilsen 'belirsiz: <bilinen kısım>' yaz. Her öğe için tam bir kayıt döndür: "
    '{"sonuclar":[{"no": <öğe numarası>, "amac": "<açıklama>"}]}.'
)


def ek_isleri(args, ist: "Istemci | None", bag) -> int:
    if not EK_OGE.exists():
        print(f"[ek] girdi yok: {EK_OGE}  (önce: python tools\\Moduller\\paketleyici31.py -K)", flush=True)
        return 0
    cache: dict[str, dict] = {}
    if EK_CACHE.exists():
        for line in EK_CACHE.open("r", encoding="utf-8", errors="replace"):
            try:
                r = json.loads(line)
            except ValueError:
                continue
            if r.get("key"):
                cache[r["key"]] = r
    tum = [json.loads(l) for l in EK_OGE.open("r", encoding="utf-8")]
    bekleyen = []
    for it in tum:
        r = cache.get(it["key"])
        if r and (r.get("valid") or r.get("deneme", 1) >= 2):
            continue
        it["_deneme"] = (r or {}).get("deneme", 0)
        bekleyen.append(it)
    plan, cur, boyut = [], [], 0
    for it in bekleyen:
        n = len(it["metin"]) + 40
        if cur and (boyut + n > EK_PARTI_KARAKTER or len(cur) >= EK_PARTI_OGE):
            plan.append(cur)
            cur, boyut = [], 0
        cur.append(it)
        boyut += n
    if cur:
        plan.append(cur)
    sayim = {t: sum(1 for x in bekleyen if x["tur"] == t) for t in ("tip", "global", "tablo")}
    print(f"[ek] toplam öğe {len(tum)}; önbellekte olmayan {len(bekleyen)} {sayim}; istek sayısı: {len(plan)}", flush=True)
    if args.dry_run or not plan or ist is None:
        return 0
    mimari = mimari_ozeti(2500)
    yazilan, started = 0, time.time()
    with EK_CACHE.open("a", encoding="utf-8") as out:
        for bi, grup in enumerate(plan, 1):
            user = f"Mimari (kısa):\n{mimari}\n\nAmacı yazılacak öğeler:\n\n" + "\n".join(
                f"### ÖĞE {n}\n{it['metin']}" for n, it in enumerate(grup, 1))
            res = ist.sor(EK_SISTEM, user, EK_SCHEMA, 8192)       # ModelHata -> zincirde sıradaki sağlayıcı kaldığı yerden sürer
            its = res.get("sonuclar", []) if isinstance(res, dict) else (res if isinstance(res, list) else [])
            got: dict[int, str] = {}
            for r in its:
                try:
                    got[int(r.get("no", 0))] = str(r.get("amac", ""))
                except (TypeError, ValueError, AttributeError):
                    continue
            gecerli_say = 0
            for n, it in enumerate(grup, 1):
                ans = pf.clean_answer(got.get(n, ""))
                gecerli = bool(ans) and len(ans) >= 15 and not pf.is_uncertain(ans)
                out.write(json.dumps({"key": it["key"], "tur": it["tur"], "ad": it["ad"], "file": it["file"], "line": it["line"],
                                      "amac": ans if gecerli else "", "ham": got.get(n, "")[:400], "valid": gecerli,
                                      "deneme": it["_deneme"] + 1, "source": ist.ad, "model": ist.model,
                                      "ts": time.strftime("%Y-%m-%dT%H:%M:%S")}, ensure_ascii=False) + "\n")
                gecerli_say += gecerli
            out.flush()
