# uXBasic durum ekranı — yalnız OKUR, hiçbir şeyi değiştirmez, anahtar değeri göstermez.
# Masaüstündeki "uXBasic Durum" kısayolu bunu açar. Elle: pwsh -NoExit -File DURUM_GOSTER.ps1
$ErrorActionPreference = 'SilentlyContinue'
$UXBC = $PSScriptRoot
$UXB = Join-Path $UXBC 'uxb'
$V4 = Join-Path $UXBC 'UxbRAG\UXB_HYBRID_RAG_V4_YORUMLU_JSON'
$OC = Join-Path $UXBC 'UXB_CONTROL_CENTER_V1_1\UXB_CONTROL_CENTER_V1_1\openclaw_uxb'
$DT = Join-Path $UXB 'docs\kitaplar\_ortak\dil_tanimi'

function Baslik([string]$s) { Write-Host ''; Write-Host "=== $s ===" -ForegroundColor Cyan }
function Iyi([string]$s) { Write-Host "  [TAMAM] $s" -ForegroundColor Green }
function Kotu([string]$s) { Write-Host "  [SORUN] $s" -ForegroundColor Yellow }
function Bilgi([string]$s) { Write-Host "  $s" }
function Satir([string]$yol) { if (Test-Path $yol) { [IO.File]::ReadAllLines($yol).Count } else { 0 } }

Write-Host "uXBasic DURUM  —  $(Get-Date -Format 'yyyy-MM-dd HH:mm')" -ForegroundColor White

# ---------------------------------------------------------------- 1. Harita doldurma
Baslik '1. Kaynak haritası doldurma (dış yapay zekâlar rutin açıklamalarını yazıyor)'
$doldurma = @(Get-CimInstance Win32_Process -Filter "Name='python.exe'" | Where-Object { $_.CommandLine -like '*uxb_harita_doldur.py*' -or $_.CommandLine -like '*uxb_gunluk_zincir.py*' -or $_.CommandLine -like '*uxb_ek_amac.py*' })
if ($doldurma.Count) { Iyi "şu an ÇALIŞIYOR (PID $($doldurma[0].ProcessId))" } else { Kotu 'şu an çalışmıyor' }
$paket = Join-Path $V4 'ajan_paketi'
$toplam = [Math]::Max(0, (Satir (Join-Path $paket 'rutinler.tsv')) - 1)
Bilgi ("dolu rutin açıklaması: {0}  (haritadaki rutin: {1})" -f (Satir (Join-Path $paket 'amac_onbellek.jsonl')), $toplam)
Bilgi ("dosya/modül özeti: {0}   soru-cevap sayfası: {1}" -f (Satir (Join-Path $paket 'modul_ozet_onbellek.jsonl')), (Satir (Join-Path $paket 'sss_onbellek.jsonl')))
$bugun = Get-Date -Format 'yyyy-MM-dd'
$kotaSatiri = foreach ($f in Get-ChildItem (Join-Path $V4 'logs') -Filter 'kota_*.json') {
    $k = Get-Content $f.FullName -Raw | ConvertFrom-Json
    $ad = $f.BaseName -replace '^kota_', ''
    if ($k.gun -eq $bugun) { "$ad $($k.istek)" } else { "$ad 0" }
}
Bilgi ("bugünkü istek sayıları: " + ($kotaSatiri -join ', ') + "   (sınırlar: kimi 100, gemini ~40, gemini2 ~240)")
$son = Get-ChildItem (Join-Path $V4 'logs') -Filter 'harita_zincir_*.log' | Sort-Object LastWriteTime -Descending | Select-Object -First 1
if ($son) {
    Bilgi "son günlük: $($son.Name)  ($($son.LastWriteTime.ToString('yyyy-MM-dd HH:mm')))"
    $engel = Select-String -Path $son.FullName -Pattern 'durdu \((KALICI|KOTA)\)' -Encoding utf8 | ForEach-Object {
        $l = $_.Line
        if ($l -match '401|Incorrect API key') { '  ChatGPT: API anahtarı GEÇERSİZ (401) — api_anahtarlari.env dosyasındaki OPENAI_API_KEY yenilenmeli' }
        elseif ($l -match 'credit balance') { '  Claude API: kredi yok (Claude Code aboneliği API kredisi değildir)' }
        elseif ($l -match '^\[(gemini\w*)/') { "  $($Matches[1]): Google ücretsiz günlük kotası doldu (Türkiye saatiyle sabah ~10:00'da yenilenir)" }
        elseif ($l -match '^\[(\w+)/') { "  $($Matches[1]): günlük istek sınırı doldu (gece yarısı yenilenir)" }
    }
    $engel | Sort-Object -Unique | ForEach-Object { Kotu $_.Trim() }
}

# ---------------------------------------------------------------- 2. Bekçi
Baslik '2. Bekçi (haritayı her gün kaldığı yerden sürdürür)'
$bekci = @(Get-CimInstance Win32_Process -Filter "Name='pwsh.exe' OR Name='powershell.exe'" | Where-Object { $_.CommandLine -like '*uxb_harita_sonrasi.ps1*' })
if ($bekci.Count) { Iyi "çalışıyor (PID $($bekci[0].ProcessId))" } else { Kotu 'çalışmıyor — başlatmak için çift tıkla: UXB_CONTROL_CENTER_V1_1\UXB_CONTROL_CENTER_V1_1\openclaw_uxb\uxb_baslangic.cmd' }
Get-Content (Join-Path $OC 'oturumlar\bekci.log') -Tail 3 -Encoding utf8 | ForEach-Object { Bilgi "günlük: $_" }

# ---------------------------------------------------------------- 3. Dil tanımı
Baslik '3. uXBasic Dil Tanımı (tek kanonik belge) — bölüm bölüm'
$alanlar = Join-Path $DT 'alanlar'
if (-not (Test-Path $alanlar) -or -not (Get-ChildItem $alanlar -Directory)) { Kotu 'henüz bölüm klasörü yok (ajanlar kaynakları okuyor olabilir)' }
foreach ($a in Get-ChildItem $alanlar -Directory | Sort-Object Name) {
    $ornek = @(Get-ChildItem (Join-Path $a.FullName 'ornekler') -Filter *.uxb).Count
    $gecen = 0
    $sj = Join-Path $a.FullName 'sonuc.json'
    if (Test-Path $sj) { $gecen = @((Get-Content $sj -Raw -Encoding utf8 | ConvertFrom-Json) | Where-Object { $_.hepsi }).Count }
    $bolum = if (Test-Path (Join-Path $a.FullName 'bolum.md')) { 'bölüm yazıldı' } else { 'bölüm yazılıyor' }
    $denetim = if (Test-Path (Join-Path $a.FullName 'denetim.md')) { 'denetlendi' } elseif (Test-Path (Join-Path $a.FullName 'codex\cevap.md')) { 'Codex cevap verdi' } elseif (Test-Path (Join-Path $a.FullName 'codex\istek.md')) { 'Codex denetliyor' } else { '' }
    Bilgi ("{0,-28} örnek {1,3}  üç motorda geçen {2,3}   {3}  {4}" -f $a.Name, $ornek, $gecen, $bolum, $denetim)
}
$belge = Join-Path $UXB 'docs\kitaplar\UXBASIC_DIL_TANIMI.md'
if (Test-Path $belge) {
    $b = Get-Item $belge
    Bilgi ("birleşik belge: docs\kitaplar\UXBASIC_DIL_TANIMI.md  ({0:N0} KB, {1})" -f ($b.Length / 1KB), $b.LastWriteTime.ToString('yyyy-MM-dd HH:mm'))
    $ke = Join-Path $DT 'kapsam_eksikleri.json'
    if (Test-Path $ke) {
        $k = Get-Content $ke -Raw -Encoding utf8 | ConvertFrom-Json
        $n = @($k.anahtar).Count + @($k.yerlesik).Count + @($k.kutuphane).Count
        if ($n -eq 0) { Iyi 'kapsam tam: her anahtar sözcük, yerleşik ad ve kütüphane belgede var' }
        else { Kotu ("belgede henüz geçmeyen: {0} anahtar sözcük, {1} yerleşik ad, {2} kütüphane" -f @($k.anahtar).Count, @($k.yerlesik).Count, @($k.kutuphane).Count) }
    }
}

# ---------------------------------------------------------------- 4. Sorun defteri
Baslik '4. Sorun defteri (uxb\ai_koordinasyon\SORUN_TAKIP.md)'
$st = Join-Path $UXB 'ai_koordinasyon\SORUN_TAKIP.md'
if (Test-Path $st) {
    $t = Get-Content $st -Encoding utf8
    $nums = @($t | Select-String -Pattern '^##+ S-(\d+)' | ForEach-Object { [int]$_.Matches[0].Groups[1].Value } | Sort-Object -Unique)
    Bilgi ("farklı S- kaydı: {0}   en büyük numara: S-{1}" -f $nums.Count, ($nums | Select-Object -Last 1))
    Bilgi 'durumlar (açık/kapalı) kayıtların içinde yazılı; toplu sayım Dil Tanımı Ek C ile verilecek'
}

# ---------------------------------------------------------------- 5. Derleyici
Baslik '5. Derleyici'
Get-ChildItem (Join-Path $UXB 'bin') -Filter 'uxb*.exe' | Sort-Object LastWriteTime -Descending | Select-Object -First 3 | ForEach-Object {
    Bilgi ("{0,-26} {1}" -f $_.Name, $_.LastWriteTime.ToString('yyyy-MM-dd HH:mm'))
}
Write-Host ''
Write-Host 'Bu pencere yalnız bilgi verir. Kapatabilirsiniz.' -ForegroundColor DarkGray

