# -*- coding: utf-8 -*-
"""Her sağlayıcıya tek kelimelik gerçek istek; yalnız durum ve kısa cevap/hata yazar (anahtar yazılmaz)."""
import json, sys, urllib.request, urllib.error, time
sys.path.insert(0, r"C:\Users\mete\Downloads\BasicOyunSource\UXBc_Clean\UXBc\UxbRAG\UXB_HYBRID_RAG_V4_YORUMLU_JSON\tools")
import uxb_harita_doldur as hd

cfg = hd.ayarlari_oku()


def post(url, body, headers, timeout=60):
    req = urllib.request.Request(url, data=json.dumps(body).encode(), headers={"Content-Type": "application/json", **headers})
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return r.status, json.load(r)
    except urllib.error.HTTPError as e:
        try:
            return e.code, json.loads(e.read().decode("utf-8", "replace"))
        except Exception:
            return e.code, {"hata": "çözülemedi"}
    except Exception as e:
        return 0, {"hata": str(e)[:160]}


def get(url, headers, timeout=30):
    req = urllib.request.Request(url, headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return r.status, json.load(r)
    except urllib.error.HTTPError as e:
        return e.code, {"hata": e.read().decode("utf-8", "replace")[:200]}
    except Exception as e:
        return 0, {"hata": str(e)[:160]}


def kisa(o):
    s = json.dumps(o, ensure_ascii=False)
    return s[:260]


MSG = [{"role": "user", "content": "Sadece tamam yaz."}]
# 1) Gemini (ücretsiz katman kota durumu)
k = cfg.get("GEMINI_API_KEY", "")
m = cfg.get("UXB_GEMINI2_MODEL", "gemini-3.5-flash")
st, d = post(f"https://generativelanguage.googleapis.com/v1beta/models/{m}:generateContent",
             {"contents": [{"role": "user", "parts": [{"text": "Sadece tamam yaz."}]}], "generationConfig": {"maxOutputTokens": 20}}, {"x-goog-api-key": k})
print("gemini2", m, st, kisa(d.get("candidates", d)) if st == 200 else kisa(d.get("error", d)))
# 2) Kimi
base = cfg.get("MOONSHOT_BASE_URL", "https://api.moonshot.ai/v1").rstrip("/")
st, d = post(base + "/chat/completions", {"model": cfg.get("UXB_KIMI_MODEL", "kimi-k2.7-code"), "max_tokens": 20, "messages": MSG}, {"Authorization": "Bearer " + cfg.get("MOONSHOT_API_KEY", "")})
print("kimi", st, kisa(d.get("choices", d)) if st == 200 else kisa(d.get("error", d)))
# 3) ChatGPT
st, d = post("https://api.openai.com/v1/chat/completions", {"model": cfg.get("UXB_CHATGPT_MODEL", "gpt-5-mini"), "max_completion_tokens": 60, "messages": MSG}, {"Authorization": "Bearer " + cfg.get("OPENAI_API_KEY", "")})
print("chatgpt", st, kisa(d.get("choices", d)) if st == 200 else kisa(d.get("error", d)))
# 4) Claude
st, d = post("https://api.anthropic.com/v1/messages", {"model": cfg.get("UXB_CLAUDE_MODEL", "claude-sonnet-5"), "max_tokens": 20, "messages": MSG},
             {"x-api-key": cfg.get("ANTHROPIC_API_KEY", ""), "anthropic-version": "2023-06-01"})
print("claude", st, kisa(d.get("content", d)) if st == 200 else kisa(d.get("error", d)))
# 5) Groq
st, d = post("https://api.groq.com/openai/v1/chat/completions", {"model": "openai/gpt-oss-20b", "max_tokens": 200, "messages": MSG}, {"Authorization": "Bearer " + cfg.get("GROQ_API_KEY", "")})
print("groq", st, kisa(d.get("choices", d)) if st == 200 else kisa(d.get("error", d)))
# 6) OmniRoute
ok = cfg.get("OMNIROUTE_API_KEY", "")
st, d = get("http://localhost:20128/v1/models", {"Authorization": "Bearer " + ok})
print("omniroute /v1/models", st, (f"{len(d.get('data', []))} model" if st == 200 else kisa(d)))
if st == 200:
    ids = [x["id"] for x in d.get("data", [])]
    print("   ilk 40:", ", ".join(ids[:40]))
    json.dump(ids, open(sys.argv[1], "w", encoding="utf-8"), ensure_ascii=False)

