def module_call_graph(ctx: Ctx) -> tuple[dict, dict]:
    """Modül düzeyinde çağrı ilişkisi: {dosya: {çağrılan dosya: çağrı sayısı}} ve tersi (dosya içi çağrılar hariç)."""
    c = getattr(ctx, "_mod_call_graph", None)
    if c is None:
        uses: dict = {}
        usedby: dict = {}
