#!/usr/bin/env python3
# -*- coding: utf-8 -*-

"""
Mete Prompt Bridge native host.

Gorev:
- GONDER klasorundeki zaman damgali en yeni .txt dosyasini okur.
- Eklentiden gelen cevabi ALINAN klasorune ayni damga ile yazar.
- Chrome/Opera native messaging protokolunu kullanir:
  4 byte mesaj uzunlugu + UTF-8 JSON.
"""

from __future__ import annotations

import json
import os
import struct
import sys
import traceback
from pathlib import Path
from datetime import datetime


ROOT = Path(__file__).resolve().parent
CONFIG_PATH = ROOT / "host_config.json"
STATE_PATH = ROOT / "state.json"


def log_err(msg: str) -> None:
    print(msg, file=sys.stderr, flush=True)


def read_message() -> dict | None:
    raw_len = sys.stdin.buffer.read(4)
    if not raw_len:
        return None
    msg_len = struct.unpack("<I", raw_len)[0]
    data = sys.stdin.buffer.read(msg_len)
    if not data:
        return None
    return json.loads(data.decode("utf-8"))


def send_message(message: dict) -> None:
    encoded = json.dumps(message, ensure_ascii=False).encode("utf-8")
    sys.stdout.buffer.write(struct.pack("<I", len(encoded)))
    sys.stdout.buffer.write(encoded)
    sys.stdout.buffer.flush()


def load_json(path: Path, default: dict) -> dict:
    if not path.exists():
        return default
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return default


def save_json(path: Path, data: dict) -> None:
    path.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")


def load_config() -> dict:
    cfg = load_json(CONFIG_PATH, {})
    send_dir = Path(cfg.get("send_dir", str(ROOT.parent / "sample_folders" / "GONDER"))).expanduser()
    received_dir = Path(cfg.get("received_dir", str(ROOT.parent / "sample_folders" / "ALINAN"))).expanduser()
    send_dir.mkdir(parents=True, exist_ok=True)
    received_dir.mkdir(parents=True, exist_ok=True)
    return {
        "send_dir": send_dir,
        "received_dir": received_dir,
        "file_glob": cfg.get("file_glob", "*.txt")
    }


def sorted_prompt_files(send_dir: Path, pattern: str) -> list[Path]:
    files = [p for p in send_dir.glob(pattern) if p.is_file()]
    # Zaman damgasi dosya adinda oldugu icin once ada gore siralar.
    # Adlar karisiksa mtime ikinci guvence olarak kullanilir.
    files.sort(key=lambda p: (p.stem, p.stat().st_mtime), reverse=True)
    return files


def latest_prompt() -> dict:
    cfg = load_config()
    state = load_json(STATE_PATH, {})
    files = sorted_prompt_files(cfg["send_dir"], cfg["file_glob"])

    if not files:
        return {"ok": True, "hasPrompt": False, "reason": "GONDER klasorunde dosya yok."}

    latest = files[0]
    last_answered = state.get("last_answered_filename")
    if latest.name == last_answered:
        return {"ok": True, "hasPrompt": False, "reason": "En yeni dosya zaten islenmis."}

    text = latest.read_text(encoding="utf-8", errors="replace")
    return {
        "ok": True,
        "hasPrompt": True,
        "filename": latest.name,
        "stamp": latest.stem,
        "text": text
    }


def save_answer(msg: dict) -> dict:
    cfg = load_config()
    stamp = msg.get("stamp") or datetime.now().strftime("%Y%m%d_%H%M%S")
    filename = msg.get("filename") or f"{stamp}.txt"
    answer = msg.get("answer", "")
    page_url = msg.get("pageUrl", "")
    page_title = msg.get("pageTitle", "")

    out = cfg["received_dir"] / f"{stamp}.txt"
    body = []
    body.append(f"STAMP: {stamp}")
    body.append(f"SOURCE_FILE: {filename}")
    body.append(f"PAGE_TITLE: {page_title}")
    body.append(f"PAGE_URL: {page_url}")
    body.append("")
    body.append("===== ANSWER =====")
    body.append(answer)
    out.write_text("\n".join(body), encoding="utf-8")

    state = load_json(STATE_PATH, {})
    state["last_answered_filename"] = filename
    state["last_answered_at"] = datetime.now().isoformat(timespec="seconds")
    save_json(STATE_PATH, state)

    return {"ok": True, "outfile": str(out)}


def save_error(msg: dict) -> dict:
    cfg = load_config()
    stamp = msg.get("stamp") or datetime.now().strftime("%Y%m%d_%H%M%S")
    filename = msg.get("filename") or f"{stamp}.txt"
    error = msg.get("error", "")

    out = cfg["received_dir"] / f"{stamp}.error.txt"
    out.write_text(f"SOURCE_FILE: {filename}\nERROR:\n{error}\n", encoding="utf-8")
    return {"ok": True, "outfile": str(out)}


def handle(msg: dict) -> dict:
    cmd = msg.get("cmd")
    if cmd == "latest_prompt":
        return latest_prompt()
    if cmd == "save_answer":
        return save_answer(msg)
    if cmd == "save_error":
        return save_error(msg)
    return {"ok": False, "error": f"Bilinmeyen komut: {cmd}"}


def main() -> None:
    try:
        msg = read_message()
        if msg is None:
            return
        send_message(handle(msg))
    except Exception as exc:
        log_err(traceback.format_exc())
        send_message({"ok": False, "error": str(exc)})


if __name__ == "__main__":
    main()

