function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

function randomInt(min, max) {
  min = Number(min || 0);
  max = Number(max || min);
  if (max < min) [min, max] = [max, min];
  return Math.floor(min + Math.random() * (max - min + 1));
}

function findElement(selector, fallbackSelectors = []) {
  const candidates = [];
  if (selector && selector.trim()) candidates.push(selector.trim());
  candidates.push(...fallbackSelectors);
  for (const sel of candidates) {
    try {
      const el = document.querySelector(sel);
      if (el) return el;
    } catch (_) {}
  }
  return null;
}

function setNativeValue(element, value) {
  const tag = (element.tagName || "").toLowerCase();

  if (element.isContentEditable || element.getAttribute("contenteditable") === "true") {
    element.focus();
    element.textContent = value;
    element.dispatchEvent(new InputEvent("input", { bubbles: true, inputType: "insertText", data: value }));
    element.dispatchEvent(new Event("change", { bubbles: true }));
    return;
  }

  if (tag === "textarea" || tag === "input") {
    element.focus();
    const prototype = tag === "textarea" ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype;
    const descriptor = Object.getOwnPropertyDescriptor(prototype, "value");
    if (descriptor && descriptor.set) descriptor.set.call(element, value);
    else element.value = value;

    element.dispatchEvent(new InputEvent("input", { bubbles: true, inputType: "insertText", data: value }));
    element.dispatchEvent(new Event("change", { bubbles: true }));
    return;
  }

  throw new Error("Prompt alani textarea/input/contenteditable degil.");
}

function findSendButton(selector) {
  const explicit = findElement(selector, []);
  if (explicit) return explicit;

  const words = ["gönder", "gonder", "send", "submit", "sor", "ask"];
  const buttons = Array.from(document.querySelectorAll("button, input[type='submit'], [role='button']"));
  for (const b of buttons) {
    const text = ((b.innerText || b.value || b.getAttribute("aria-label") || "") + "").toLowerCase();
    if (words.some(w => text.includes(w))) return b;
  }
  return null;
}

function getResponseText(selector) {
  if (selector && selector.trim()) {
    const nodes = Array.from(document.querySelectorAll(selector.trim()));
    if (nodes.length) return nodes.map(n => n.innerText || n.textContent || "").join("\n\n").trim();
  }
  return (document.body.innerText || document.body.textContent || "").trim();
}

async function waitForStableResponse(selector, baseline, maxWaitMs, stableMs) {
  const start = Date.now();
  let last = "";
  let lastChange = Date.now();

  while (Date.now() - start < maxWaitMs) {
    const current = getResponseText(selector);
    const changedEnough = current && current !== baseline && current.length >= Math.max(20, baseline.length + 5);

    if (changedEnough && current !== last) {
      last = current;
      lastChange = Date.now();
    }

    if (changedEnough && Date.now() - lastChange >= stableMs) {
      return current;
    }

    await sleep(500);
  }

  const finalText = getResponseText(selector);
  if (finalText && finalText !== baseline) return finalText;
  throw new Error("Cevap bekleme suresi doldu veya sayfa metni degismedi.");
}

async function fillSendCollect(promptText, settings) {
  const input = findElement(settings.inputSelector, ["textarea", "[contenteditable='true']", "input[type='text']"]);
  if (!input) throw new Error("Prompt alani bulunamadi. Ayarlardan inputSelector gir.");

  const before = getResponseText(settings.responseSelector);

  setNativeValue(input, promptText);

  await sleep(randomInt(settings.minDelayMs, settings.maxDelayMs));

  const button = findSendButton(settings.sendSelector);
  if (!button) throw new Error("Gonder butonu bulunamadi. Ayarlardan sendSelector gir.");

  button.click();

  const answer = await waitForStableResponse(
    settings.responseSelector,
    before,
    Number(settings.maxWaitMs || 120000),
    Number(settings.stableMs || 5000)
  );

  return answer;
}

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  (async () => {
    if (message.cmd === "ping") {
      sendResponse({ ok: true });
      return;
    }

    if (message.cmd === "fill_send_collect") {
      const answer = await fillSendCollect(message.promptText || "", message.settings || {});
      sendResponse({ ok: true, answer });
      return;
    }

    sendResponse({ ok: false, error: "Bilinmeyen content komutu." });
  })().catch(err => {
    sendResponse({ ok: false, error: err.message });
  });
  return true;
});

