13	let running = false;
14	let busy = false;
15	let loopTimer = null;
16	
17	function nativeMessage(message) {
18	  return new Promise((resolve, reject) => {
19	    chrome.runtime.sendNativeMessage(HOST_NAME, message, (response) => {
20	      const err = chrome.runtime.lastError;
21	      if (err) reject(new Error(err.message));
22	      else resolve(response);
23	    });
24	  });
25	}
