27	async function getSettings() {
28	  const data = await chrome.storage.local.get(DEFAULTS);
29	  return { ...DEFAULTS, ...data };
30	}
31	
32	async function setStatus(text) {
33	  await chrome.storage.local.set({ lastStatus: `${new Date().toLocaleString()} - ${text}` });
34	}
35	
36	async function getActiveTab() {
37	  const tabs = await chrome.tabs.query({ active: true, currentWindow: true });
38	  return tabs && tabs[0] ? tabs[0] : null;
39	}
