41	async function ensureContentScript(tabId) {
42	  try {
43	    await chrome.tabs.sendMessage(tabId, { cmd: "ping" });
44	  } catch (_) {
45	    await chrome.scripting.executeScript({
46	      target: { tabId },
47	      files: ["content.js"]
48	    });
49	  }
50	}
