52	async function processOnce() {
53	  if (busy) return;
54	  busy = true;
55	  try {
56	    const promptInfo = await nativeMessage({ cmd: "latest_prompt" });
57	    if (!promptInfo || !promptInfo.ok) {
58	      await setStatus(`Native host hatasi: ${promptInfo ? promptInfo.error : "cevap yok"}`);
59	      return;
60	    }
61	    if (!promptInfo.hasPrompt) {
62	      await setStatus("Yeni prompt yok.");
63	      return;
64	    }
65	
66	    const tab = await getActiveTab();
67	    if (!tab || !tab.id) {
68	      await setStatus("Aktif sekme bulunamadi.");
69	      return;
70	    }
71	
72	    const settings = await getSettings();
73	    await ensureContentScript(tab.id);
74	
75	    const result = await chrome.tabs.sendMessage(tab.id, {
76	      cmd: "fill_send_collect",
77	      promptText: promptInfo.text,
78	      stamp: promptInfo.stamp,
79	      filename: promptInfo.filename,
80	      settings
81	    });
82	
83	    if (!result || !result.ok) {
84	      await nativeMessage({
85	        cmd: "save_error",
86	        stamp: promptInfo.stamp,
87	        filename: promptInfo.filename,
88	        error: result ? result.error : "Sayfadan cevap gelmedi."
89	      });
90	      await setStatus(`Sayfa isleme hatasi: ${result ? result.error : "cevap yok"}`);
91	      return;
92	    }
93	
94	    const saveResult = await nativeMessage({
95	      cmd: "save_answer",
96	      stamp: promptInfo.stamp,
97	      filename: promptInfo.filename,
98	      answer: result.answer,
99	      pageUrl: tab.url || "",
100	      pageTitle: tab.title || ""
101	    });
102	
103	    if (!saveResult || !saveResult.ok) {
104	      await setStatus(`Cevap kaydedilemedi: ${saveResult ? saveResult.error : "cevap yok"}`);
105	      return;
106	    }
107	
108	    await setStatus(`Tamamlandi: ${promptInfo.filename} -> ${saveResult.outfile}`);
109	  } catch (err) {
110	    await setStatus(`Hata: ${err.message}`);
111	  } finally {
112	    busy = false;
113	  }
114	}
115	
116	function scheduleLoop() {
117	  if (loopTimer) clearTimeout(loopTimer);
118	  if (!running) return;
119	  loopTimer = setTimeout(async () => {
120	    await processOnce();
121	    scheduleLoop();
122	  }, 3000);
123	}
124	
125	chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
126	  (async () => {
127	    if (message.cmd === "start") {
128	      running = true;
129	      await setStatus("Calisma basladi.");
130	      scheduleLoop();
131	      sendResponse({ ok: true });
132	    } else if (message.cmd === "stop") {
133	      running = false;
134	      if (loopTimer) clearTimeout(loopTimer);
135	      await setStatus("Calisma durdu.");
136	      sendResponse({ ok: true });
137	    } else if (message.cmd === "once") {
138	      await processOnce();
139	      sendResponse({ ok: true });
140	    } else if (message.cmd === "status") {
141	      const data = await chrome.storage.local.get(["lastStatus"]);
142	      sendResponse({ ok: true, running, busy, lastStatus: data.lastStatus || "" });
143	    } else {
144	      sendResponse({ ok: false, error: "Bilinmeyen komut" });
