PROVIDERS = ("gemini", "chatgpt", "claude")
# Chrome/Opera native messaging: host -> eklenti tek mesaj en fazla 1 MB. Daha uzun istem parcalanir.
CHUNK_CHARS = 300_000


def is_answered(cfg: dict, stem: str) -> bool:
    d = cfg["received_dir"]
    return (d / f"{stem}.txt").exists() or (d / f"{stem}.error.txt").exists()


def parse_directives(text: str, stem: str) -> tuple[dict, str]:
    """Istem dosyasinin basindaki '#KOPRU anahtar=deger ...' satirlarini ayirir.
    Saglayici yoksa dosya adindan (gemini/chatgpt/claude) anlasilir."""
    opts: dict = {}
    lines = text.splitlines()
    i = 0
    while i < len(lines) and lines[i].startswith("#KOPRU"):
        for part in lines[i].split()[1:]:
            if "=" in part:
                k, v = part.split("=", 1)
                opts[k.strip()] = v.strip()
        i += 1
    body = "\n".join(lines[i:])
    if "saglayici" not in opts:
        low = stem.lower()
        for p in PROVIDERS:
            if p in low:
                opts["saglayici"] = p
                break
    return opts, body


def pending_files(cfg: dict, state: dict) -> list[Path]:
    """Cevabi olmayan istekler, EN ESKISI ONCE. Yalnizca kuyruk_baslangic'tan sonra gelenler (eski 200 dosya tekrar gonderilmesin)."""
    start = float(state.get("kuyruk_baslangic", 0))
    out = []
    for p in cfg["send_dir"].glob(cfg["file_glob"]):
        if not p.is_file() or p.stat().st_mtime < start or is_answered(cfg, p.stem):
            continue
        out.append(p)
    out.sort(key=lambda p: (p.stat().st_mtime, p.stem))
    return out


def latest_prompt(msg: dict | None = None) -> dict:
    cfg = load_config()
    state = load_json(STATE_PATH, {})
    if "kuyruk_baslangic" not in state:
        state["kuyruk_baslangic"] = datetime.now().timestamp()
        save_json(STATE_PATH, state)
    files = pending_files(cfg, state)

    if not files:
        return {"ok": True, "hasPrompt": False, "reason": "Bekleyen istek yok."}

    latest = files[0]
    raw = latest.read_text(encoding="utf-8", errors="replace")
    opts, body = parse_directives(raw, latest.stem)
    offset = int((msg or {}).get("offset", 0))
    chunk = body[offset:offset + CHUNK_CHARS]
    return {
        "ok": True,
        "hasPrompt": True,
        "filename": latest.name,
        "stamp": latest.stem,
        "options": opts,
        "totalChars": len(body),
        "offset": offset,
        "text": chunk,
        "more": offset + CHUNK_CHARS < len(body),
    }

