    send_dir = Path(cfg.get("send_dir", str(ROOT.parent / "sample_folders" / "GONDER"))).expanduser()
    received_dir = Path(cfg.get("received_dir", str(ROOT.parent / "sample_folders" / "ALINAN"))).expanduser()
    send_dir.mkdir(parents=True, exist_ok=True)
    received_dir.mkdir(parents=True, exist_ok=True)
    return {
        "send_dir": send_dir,
        "received_dir": received_dir,
        "file_glob": cfg.get("file_glob", "*.txt")
    }


def sorted_prompt_files(send_dir: Path, pattern: str) -> list[Path]:
    files = [p for p in send_dir.glob(pattern) if p.is_file()]
    # Zaman damgasi dosya adinda oldugu icin once ada gore siralar.
    # Adlar karisiksa mtime ikinci guvence olarak kullanilir.
    files.sort(key=lambda p: (p.stem, p.stat().st_mtime), reverse=True)
    return files


PROVIDERS = ("gemini", "chatgpt", "claude")
# Chrome/Opera native messaging: host -> eklenti tek mesaj en fazla 1 MB. Daha uzun istem parcalanir.
CHUNK_CHARS = 300_000


def is_answered(cfg: dict, stem: str) -> bool:
    d = cfg["received_dir"]
    return (d / f"{stem}.txt").exists() or (d / f"{stem}.error.txt").exists()


def parse_directives(text: str, stem: str) -> tuple[dict, str]:
    """Istem dosyasinin basindaki '#KOPRU anahtar=deger ...' satirlarini ayirir.
    Saglayici yoksa dosya adindan (gemini/chatgpt/claude) anlasilir."""
    opts: dict = {}
    lines = text.splitlines()
    i = 0
    while i < len(lines) and lines[i].startswith("#KOPRU"):
        for part in lines[i].split()[1:]:
            if "=" in part:
                k, v = part.split("=", 1)
                opts[k.strip()] = v.strip()
        i += 1
    body = "\n".join(lines[i:])
    if "saglayici" not in opts:
        low = stem.lower()
        for p in PROVIDERS:
            if p in low:
                opts["saglayici"] = p
                break
    return opts, body


def pending_files(cfg: dict, state: dict) -> list[Path]:
    """Cevabi olmayan istekler, EN ESKISI ONCE. Yalnizca kuyruk_baslangic'tan sonra gelenler (eski 200 dosya tekrar gonderilmesin)."""
    start = float(state.get("kuyruk_baslangic", 0))
    out = []
    for p in cfg["send_dir"].glob(cfg["file_glob"]):
        if not p.is_file() or p.stat().st_mtime < start or is_answered(cfg, p.stem):
            continue
        out.append(p)
    out.sort(key=lambda p: (p.stat().st_mtime, p.stem))
    return out


def latest_prompt(msg: dict | None = None) -> dict:
    cfg = load_config()
    state = load_json(STATE_PATH, {})
    if "kuyruk_baslangic" not in state:
        state["kuyruk_baslangic"] = datetime.now().timestamp()
        save_json(STATE_PATH, state)
    files = pending_files(cfg, state)

    if not files:
        return {"ok": True, "hasPrompt": False, "reason": "Bekleyen istek yok."}

    latest = files[0]
    raw = latest.read_text(encoding="utf-8", errors="replace")
    opts, body = parse_directives(raw, latest.stem)
    offset = int((msg or {}).get("offset", 0))
    chunk = body[offset:offset + CHUNK_CHARS]
    return {
        "ok": True,
        "hasPrompt": True,
        "filename": latest.name,
        "stamp": latest.stem,
        "options": opts,
        "totalChars": len(body),
        "offset": offset,
        "text": chunk,
        "more": offset + CHUNK_CHARS < len(body),
    }


def save_answer(msg: dict) -> dict:
    cfg = load_config()
    stamp = msg.get("stamp") or datetime.now().strftime("%Y%m%d_%H%M%S")
    filename = msg.get("filename") or f"{stamp}.txt"
    answer = msg.get("answer", "")
    page_url = msg.get("pageUrl", "")
    page_title = msg.get("pageTitle", "")

    out = cfg["received_dir"] / f"{stamp}.txt"
    body = []
    body.append(f"STAMP: {stamp}")
    body.append(f"SOURCE_FILE: {filename}")
    body.append(f"PAGE_TITLE: {page_title}")
    body.append(f"PAGE_URL: {page_url}")
    body.append("")
    body.append("===== ANSWER =====")
    body.append(answer)
    out.write_text("\n".join(body), encoding="utf-8")

    state = load_json(STATE_PATH, {})
    state["last_answered_filename"] = filename
    state["last_answered_at"] = datetime.now().isoformat(timespec="seconds")
    save_json(STATE_PATH, state)

    return {"ok": True, "outfile": str(out)}


def save_error(msg: dict) -> dict:
    cfg = load_config()
    stamp = msg.get("stamp") or datetime.now().strftime("%Y%m%d_%H%M%S")
    filename = msg.get("filename") or f"{stamp}.txt"
    error = msg.get("error", "")

    out = cfg["received_dir"] / f"{stamp}.error.txt"
    out.write_text(f"SOURCE_FILE: {filename}\nERROR:\n{error}\n", encoding="utf-8")
    return {"ok": True, "outfile": str(out)}


def handle(msg: dict) -> dict:
    cmd = msg.get("cmd")
    if cmd == "latest_prompt":
        return latest_prompt()
    if cmd == "save_answer":
        return save_answer(msg)
    if cmd == "save_error":
        return save_error(msg)
    return {"ok": False, "error": f"Bilinmeyen komut: {cmd}"}


def main() -> None:
    try:
        msg = read_message()
        if msg is None:
            return
        send_message(handle(msg))
    except Exception as exc:
        log_err(traceback.format_exc())
        send_message({"ok": False, "error": str(exc)})


if __name__ == "__main__":
    main()

