// Mete Prompt Bridge 0.2 - sayfa tarafi.
// Eski surumun sorunu: cevap, "sayfa metni degisti mi" diye TUM sayfadan alinirdi; sayfa degisince / sohbet
// yenilenince ayni ya da yanlis metin kaydediliyordu. Burada saglayiciya ozel adaptorler var:
// cevap yalnizca YENI asistan mesajindan alinir ve uretim bitene (durdur dugmesi kaybolana) kadar beklenir.

function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

function randomInt(min, max) {
  min = Number(min || 0);
  max = Number(max || min);
  if (max < min) [min, max] = [max, min];
  return Math.floor(min + Math.random() * (max - min + 1));
}

function qsa(selectors) {
  for (const sel of selectors) {
    try {
      const list = Array.from(document.querySelectorAll(sel));
      if (list.length) return list;
    } catch (_) {}
  }
  return [];
}

function visible(el) {
  if (!el) return false;
  const r = el.getBoundingClientRect();
  const st = getComputedStyle(el);
  return r.width > 0 && r.height > 0 && st.visibility !== "hidden" && st.display !== "none";
}

function firstVisible(selectors) {
  for (const el of qsa(selectors)) if (visible(el)) return el;
  return null;
}

// Saglayici adaptorleri. Secici listeleri sirayla denenir (siteler sik degisir; ayarlardan da eklenebilir).
const ADAPTERS = {
  chatgpt: {
    host: /(^|\.)chatgpt\.com$|(^|\.)chat\.openai\.com$/,
    input: ["#prompt-textarea", "div.ProseMirror[contenteditable='true']", "textarea"],
    send: ["button[data-testid='send-button']", "button[aria-label*='Send']", "button[aria-label*='Gönder']"],
    stop: ["button[data-testid='stop-button']", "button[aria-label*='Stop']", "button[aria-label*='Durdur']"],
    assistant: ["[data-message-author-role='assistant']"]
  },
  gemini: {
    host: /(^|\.)gemini\.google\.com$/,
    input: ["rich-textarea .ql-editor", "div.ql-editor[contenteditable='true']", "[contenteditable='true']", "textarea"],
    send: ["button.send-button", "button[aria-label*='Send']", "button[aria-label*='Gönder']", "button[mattooltip*='Send']"],
    stop: ["button.stop", "button[aria-label*='Stop']", "button[aria-label*='Durdur']", "button[aria-label*='Yanıtı durdur']"],
    assistant: ["model-response .markdown", "model-response message-content", "message-content", ".model-response-text"]
  },
  claude: {
    host: /(^|\.)claude\.ai$/,
    input: ["div.ProseMirror[contenteditable='true']", "[contenteditable='true']", "textarea"],
    send: ["button[aria-label='Send message']", "button[aria-label*='Send']", "button[aria-label*='Gönder']"],
    stop: ["button[aria-label='Stop response']", "button[aria-label*='Stop']", "button[aria-label*='Durdur']"],
    assistant: ["div.font-claude-response", "div.font-claude-message", "[data-is-streaming]"]
  }
};

function detectProvider(hint) {
  if (hint && ADAPTERS[hint]) return hint;
  for (const [name, a] of Object.entries(ADAPTERS)) if (a.host.test(location.hostname)) return name;
  return null;
}

function adapterFor(hint, settings) {
  const name = detectProvider(hint);
  const base = name ? ADAPTERS[name] : { input: [], send: [], stop: [], assistant: [] };
  const extra = (s) => (s && s.trim() ? [s.trim()] : []);
  return {
    name,
    input: [...extra(settings.inputSelector), ...base.input, "textarea", "[contenteditable='true']"],
    send: [...extra(settings.sendSelector), ...base.send],
    stop: base.stop,
    assistant: [...extra(settings.responseSelector), ...base.assistant]
  };
}

function assistantMessages(ad) {
  return qsa(ad.assistant).map(n => (n.innerText || n.textContent || "").trim());
}

function isGenerating(ad) {
  return !!firstVisible(ad.stop);
}

function setPrompt(el, value) {
  el.focus();
  const tag = (el.tagName || "").toLowerCase();
  if (tag === "textarea" || tag === "input") {
    const proto = tag === "textarea" ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype;
    const d = Object.getOwnPropertyDescriptor(proto, "value");
    if (d && d.set) d.set.call(el, value); else el.value = value;
    el.dispatchEvent(new InputEvent("input", { bubbles: true, inputType: "insertText", data: value }));
    el.dispatchEvent(new Event("change", { bubbles: true }));
    return;
  }
  // contenteditable (ProseMirror / Quill): once icerigi sec-sil, sonra yapistirma olayi ile ekle.
  const sel = window.getSelection();
  const range = document.createRange();
  range.selectNodeContents(el);
  sel.removeAllRanges();
  sel.addRange(range);
  document.execCommand("delete");
  let ok = false;
  try {
    const dt = new DataTransfer();
    dt.setData("text/plain", value);
    ok = el.dispatchEvent(new ClipboardEvent("paste", { clipboardData: dt, bubbles: true, cancelable: true }));
    // paste olayi iptal edildiyse (preventDefault) editor kendisi eklemistir
    ok = !ok;
  } catch (_) { ok = false; }
  if (!ok || !(el.innerText || "").trim()) {
    document.execCommand("insertText", false, value);
  }
  if (!(el.innerText || "").trim()) {
    el.textContent = value;
    el.dispatchEvent(new InputEvent("input", { bubbles: true, inputType: "insertText", data: value }));
  }
}

async function clickSend(ad, input) {
  for (let i = 0; i < 20; i++) {   // editor metni isleyince dugme etkinlesir
    const b = firstVisible(ad.send);
    if (b && !b.disabled && b.getAttribute("aria-disabled") !== "true") { b.click(); return "dugme"; }
    await sleep(300);
  }
  input.focus();
  for (const type of ["keydown", "keypress", "keyup"]) {
    input.dispatchEvent(new KeyboardEvent(type, { key: "Enter", code: "Enter", keyCode: 13, which: 13, bubbles: true, cancelable: true }));
  }
  return "enter";
}

async function waitForNewAnswer(ad, countBefore, lastBefore, maxWaitMs, stableMs) {
  const start = Date.now();
  let seenGenerating = false;
  let last = "";
  let lastChange = Date.now();
  while (Date.now() - start < maxWaitMs) {
    const msgs = assistantMessages(ad);
    const cur = msgs.length ? msgs[msgs.length - 1] : "";
    const isNew = msgs.length > countBefore || (cur && cur !== lastBefore);
    const gen = isGenerating(ad);
    if (gen) seenGenerating = true;
    if (isNew && cur !== last) { last = cur; lastChange = Date.now(); }
    // bitti: yeni mesaj var, uretim gostergesi yok, metin stableMs boyunca degismedi
    if (isNew && last && !gen && Date.now() - lastChange >= stableMs) return last;
    await sleep(500);
  }
  // sure doldu: uretim hala suruyorsa yarim cevabi "tamam" diye kaydetme
  if (isGenerating(ad)) throw new Error("Cevap sure icinde bitmedi (uretim suruyor).");
  const msgs = assistantMessages(ad);
  const cur = msgs.length ? msgs[msgs.length - 1] : "";
  if (cur && (msgs.length > countBefore || cur !== lastBefore)) return cur;
  throw new Error(seenGenerating ? "Cevap alinamadi." : "Yeni asistan mesaji gorunmedi (secicileri kontrol et).");
}

async function fillSendCollect(promptText, settings, hint) {
  const ad = adapterFor(hint, settings);
  const input = firstVisible(ad.input);
  if (!input) throw new Error("Prompt alani bulunamadi (" + (ad.name || "bilinmeyen site") + ").");

  const before = assistantMessages(ad);
  const countBefore = before.length;
  const lastBefore = countBefore ? before[countBefore - 1] : "";

  setPrompt(input, promptText);
  await sleep(randomInt(settings.minDelayMs, settings.maxDelayMs));
  await clickSend(ad, input);

  const answer = await waitForNewAnswer(ad, countBefore, lastBefore,
    Number(settings.maxWaitMs || 600000), Number(settings.stableMs || 5000));
  return { answer, provider: ad.name || "", url: location.href };
}

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  (async () => {
    if (message.cmd === "ping") {
      sendResponse({ ok: true, provider: detectProvider(null), url: location.href });
      return;
    }
    if (message.cmd === "fill_send_collect") {
      const r = await fillSendCollect(message.promptText || "", message.settings || {}, message.provider || null);
      sendResponse({ ok: true, ...r });
      return;
    }
    sendResponse({ ok: false, error: "Bilinmeyen content komutu." });
  })().catch(err => {
    sendResponse({ ok: false, error: err.message });
  });
  return true;
});

