// Mete Prompt Bridge 0.2 - arka plan.
// - Kendiliginden baslar (tarayici acilinca / eklenti yuklenince) ve MV3 servis calisani uyusa bile alarmla uyanir.
// - Istegin saglayicisina (gemini/chatgpt/claude) gore DOGRU sekmeyi bulur; aktif sekmeye bagli degildir.
// - Uzun istemi 300k karakterlik parcalar halinde native host'tan alir (1 MB mesaj siniri).
// - Her saglayici icin sohbet adresini hatirlar; sayfa/sohbet degistiyse cevap dosyasina CONTEXT_OK: false yazar,
//   boylece orkestrator sistem baglamini yeniden gonderir.

const HOST_NAME = "com.mete.promptbridge";

const DEFAULTS = {
  inputSelector: "",
  sendSelector: "",
  responseSelector: "",
  minDelayMs: 500,
  maxDelayMs: 3000,
  maxWaitMs: 600000,
  stableMs: 5000,
  autoStart: true
};

const TAB_PATTERNS = {
  gemini: ["https://gemini.google.com/*"],
  chatgpt: ["https://chatgpt.com/*", "https://chat.openai.com/*"],
  claude: ["https://claude.ai/*"]
};

let busy = false;

function nativeMessage(message) {
  return new Promise((resolve, reject) => {
    chrome.runtime.sendNativeMessage(HOST_NAME, message, (response) => {
      const err = chrome.runtime.lastError;
      if (err) reject(new Error(err.message));
      else resolve(response);
    });
  });
}

async function getSettings() {
  const data = await chrome.storage.local.get(DEFAULTS);
  return { ...DEFAULTS, ...data };
}

async function setStatus(text) {
  await chrome.storage.local.set({ lastStatus: `${new Date().toLocaleString()} - ${text}` });
}

async function findTab(provider) {
  if (provider && TAB_PATTERNS[provider]) {
    const tabs = await chrome.tabs.query({ url: TAB_PATTERNS[provider] });
    if (tabs.length) {
      tabs.sort((a, b) => (b.lastAccessed || 0) - (a.lastAccessed || 0));
      return tabs[0];
    }
    return null;   // istenen site acik degil: baska siteye GONDERME
  }
  const tabs = await chrome.tabs.query({ active: true, currentWindow: true });
  return tabs && tabs[0] ? tabs[0] : null;
}

async function ensureContentScript(tabId) {
  try {
    await chrome.tabs.sendMessage(tabId, { cmd: "ping" });
  } catch (_) {
    await chrome.scripting.executeScript({ target: { tabId }, files: ["content.js"] });
  }
}

async function fetchFullPrompt(first) {
  let text = first.text || "";
  let info = first;
  while (info.more) {
    info = await nativeMessage({ cmd: "latest_prompt", offset: text.length });
    if (!info || !info.ok || !info.hasPrompt || info.stamp !== first.stamp) throw new Error("Istem parcalari alinamadi.");
    text += info.text || "";
  }
  return text;
}

async function processOnce() {
  if (busy) return;
  busy = true;
  try {
    const promptInfo = await nativeMessage({ cmd: "latest_prompt", offset: 0 });
    if (!promptInfo || !promptInfo.ok) {
      await setStatus(`Native host hatasi: ${promptInfo ? promptInfo.error : "cevap yok"}`);
      return;
    }
    if (!promptInfo.hasPrompt) {
      await setStatus("Bekleyen istek yok.");
      return;
    }
    const opts = promptInfo.options || {};
    const provider = opts.saglayici || null;
    const fail = async (msg) => {
      await nativeMessage({ cmd: "save_error", stamp: promptInfo.stamp, filename: promptInfo.filename, error: msg });
      await setStatus(`Hata (${promptInfo.filename}): ${msg}`);
    };

    const tab = await findTab(provider);
    if (!tab || !tab.id) {
      // sekme yoksa hata dosyasi yaz: orkestrator zincirde siradaki saglayiciya gecer
      await fail(`${provider || "aktif"} sekmesi Opera'da acik degil.`);
      return;
    }

    const text = await fetchFullPrompt(promptInfo);
    const settings = await getSettings();
    await ensureContentScript(tab.id);

    const key = `chatUrl_${provider || "genel"}`;
    const saved = (await chrome.storage.local.get([key]))[key] || "";
    const contextOk = !saved || saved === tab.url || opts.yeni_sohbet === "1";

    const result = await chrome.tabs.sendMessage(tab.id, {
      cmd: "fill_send_collect",
      promptText: text,
      provider,
      stamp: promptInfo.stamp,
      settings
    });

    if (!result || !result.ok) {
      await fail(result ? result.error : "Sayfadan cevap gelmedi.");
      return;
    }

    const after = await chrome.tabs.get(tab.id);
    await chrome.storage.local.set({ [key]: after.url || tab.url || "" });

    const saveResult = await nativeMessage({
      cmd: "save_answer",
      stamp: promptInfo.stamp,
      filename: promptInfo.filename,
      answer: result.answer,
      provider: result.provider || provider || "",
      contextOk,
      pageUrl: after.url || "",
      pageTitle: after.title || ""
    });
    if (!saveResult || !saveResult.ok) {
      await setStatus(`Cevap kaydedilemedi: ${saveResult ? saveResult.error : "cevap yok"}`);
      return;
    }
    await setStatus(`Tamamlandi: ${promptInfo.filename} -> ${saveResult.outfile}`);
  } catch (err) {
    await setStatus(`Hata: ${err.message}`);
  } finally {
    busy = false;
  }
}

async function tick() {
  const s = await getSettings();
  if (!s.autoStart) return;
  await processOnce();
}

// MV3 servis calisani uyursa alarm uyandirir (en kucuk aralik 30 sn); calisirken kendi 3 sn dongusu de var.
chrome.alarms.create("kopru_nabiz", { periodInMinutes: 0.5 });
chrome.alarms.onAlarm.addListener((a) => { if (a.name === "kopru_nabiz") tick(); });
chrome.runtime.onStartup.addListener(() => { tick(); });
chrome.runtime.onInstalled.addListener(() => { tick(); });

let fast = null;
function fastLoop() {
  if (fast) return;
  fast = setInterval(() => { tick(); }, 3000);
}
fastLoop();

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  (async () => {
    if (message.cmd === "start") {
      await chrome.storage.local.set({ autoStart: true });
      await setStatus("Calisma basladi.");
      sendResponse({ ok: true });
    } else if (message.cmd === "stop") {
      await chrome.storage.local.set({ autoStart: false });
      await setStatus("Calisma durdu.");
      sendResponse({ ok: true });
    } else if (message.cmd === "once") {
      await processOnce();
      sendResponse({ ok: true });
    } else if (message.cmd === "status") {
      const data = await chrome.storage.local.get(["lastStatus"]);
      const s = await getSettings();
      sendResponse({ ok: true, running: !!s.autoStart, busy, lastStatus: data.lastStatus || "" });
    } else {
      sendResponse({ ok: false, error: "Bilinmeyen komut" });
    }
  })();
  return true;
});

