    """Dakikalık istek + dakikalık girdi token'ı + günlük/çalıştırma başına istek sınırı; günlük sayaç diskte."""

    def __init__(self, saglayici: str, rpm: float, rpd: int, tpm: int, max_istek: int) -> None:
