        self.run_count, self.last = 0, 0.0
        self.sent: deque[tuple[float, int]] = deque()
        self.day = time.strftime("%Y-%m-%d")
        self.count = 0
        try:
            st = json.loads(self.state.read_text(encoding="utf-8"))
            if st.get("gun") == self.day:
                self.count = int(st.get("istek", 0))
        except (OSError, ValueError):
            pass

    def bekle(self, chars: int) -> str:
        if self.rpd and self.count >= self.rpd:
            return "GUNLUK_KOTA"
        if self.max_istek and self.run_count >= self.max_istek:
            return "CALISMA_SINIRI"
        tokens = int(chars / 3.2) + 1
        while True:
            now = time.time()
            while self.sent and now - self.sent[0][0] > 60:
                self.sent.popleft()
            used = sum(t for _, t in self.sent)
            if not self.sent or not self.tpm or used + tokens <= self.tpm:
                break
            time.sleep(max(1.0, 60 - (now - self.sent[0][0]) + 0.5))
        gap = time.time() - self.last
        if gap < self.min_gap:
            time.sleep(self.min_gap - gap)
        self.last = time.time()
        self.sent.append((self.last, tokens))
        return ""

    def say(self) -> None:
        self.count += 1
        self.run_count += 1
        self.state.parent.mkdir(parents=True, exist_ok=True)
        self.state.write_text(json.dumps({"gun": self.day, "istek": self.count}), encoding="utf-8")


class ModelHata(Exception):
    """kind: KOTA (günlük sınır), SINIR (çalıştırma sınırı), KALICI (anahtar/model — sağlayıcı değiştir), GECICI."""

    def __init__(self, kind: str, msg: str) -> None:
        super().__init__(msg)
        self.kind = kind


