def gemini_semasi(schema: dict) -> dict:
    s = copy.deepcopy(schema)

    def walk(n: dict) -> dict:
        n.pop("additionalProperties", None)
        if "type" in n:
            n["type"] = n["type"].upper()
        for v in (n.get("properties") or {}).values():
            walk(v)
        if isinstance(n.get("items"), dict):
            walk(n["items"])
        return n

    return walk(s)


def http_json(url: str, body: dict, headers: dict, timeout: int = 600) -> dict:
    # Groq (Cloudflare) varsayılan "Python-urllib" başlığını reddeder (403); tanımlayıcı bir User-Agent gönderilir.
    req = urllib.request.Request(url, data=json.dumps(body).encode("utf-8"),
                                 headers={"Content-Type": "application/json", "User-Agent": "uxb-harita/1.0", **headers})
    with urllib.request.urlopen(req, timeout=timeout) as r:
        return json.load(r)


