    # ---- dosya yükleme (bir kere) ----
    def yukle(self, parca: dict) -> str | None:
        """Paket parçasını bir kere yükler; kimliğini döndürür. Desteklemeyen sağlayıcıda None (metin gider)."""
        if not (self.ad.startswith("gemini") or self.ad == "claude"):
            return None
        rec = self.yuklemeler.get(parca["sha"])
        if rec and (self.ad == "claude" or time.time() - rec.get("t", 0) < YUKLEME_OMRU_SN):
            return rec["id"]
        data = Path(parca["parca"]).read_bytes()
        if self.ad.startswith("gemini"):
            start = urllib.request.Request(
                "https://generativelanguage.googleapis.com/upload/v1beta/files",
                data=json.dumps({"file": {"display_name": parca["ad"]}}).encode("utf-8"),
                headers={"x-goog-api-key": self.key, "X-Goog-Upload-Protocol": "resumable",
                         "X-Goog-Upload-Command": "start", "X-Goog-Upload-Header-Content-Length": str(len(data)),
                         "X-Goog-Upload-Header-Content-Type": "text/plain", "Content-Type": "application/json"})
            with urllib.request.urlopen(start, timeout=120) as r:
                up_url = r.headers.get("x-goog-upload-url")
            if not up_url:
                raise ModelHata("GECICI", "Gemini yükleme adresi alınamadı")
            put = urllib.request.Request(up_url, data=data, headers={
                "X-Goog-Upload-Offset": "0", "X-Goog-Upload-Command": "upload, finalize",
                "Content-Length": str(len(data))})
            with urllib.request.urlopen(put, timeout=600) as r:
                fid = json.load(r)["file"]["uri"]
        else:
            self._claude_sdk()
            up = self._claude.files.upload(file=(parca["ad"], data, "text/plain"))
            fid = up.id
        self.yuklemeler[parca["sha"]] = {"id": fid, "t": time.time(), "ad": parca["ad"]}
        self.yuk_path.parent.mkdir(parents=True, exist_ok=True)
        self.yuk_path.write_text(json.dumps(self.yuklemeler, ensure_ascii=False, indent=1), encoding="utf-8")
        print(f"   [{self.ad}] paket yüklendi (bir kere): {parca['ad']}", flush=True)
        return fid

