    tmp.replace(gonder / (stem + ".txt"))   # atomik: eklenti yarım dosya görmesin
    son = time.time() + KOPRU_BEKLE_SN
    while time.time() < son:
        hata = alinan / (stem + ".error.txt")
        tamam = alinan / (stem + ".txt")
        if hata.exists():
            raise ModelHata("GECICI", "KOPRU: " + hata.read_text(encoding="utf-8", errors="replace")[-300:].replace("\n", " "))
        if tamam.exists():
            raw = tamam.read_text(encoding="utf-8", errors="replace")
            ust, _, cevap = raw.partition("===== ANSWER =====")
            bas = dict(l.split(": ", 1) for l in ust.splitlines() if ": " in l)
