    tmp.replace(gonder / (stem + ".txt"))   # atomik: eklenti yarım dosya görmesin
    son = time.time() + KOPRU_BEKLE_SN
    while time.time() < son:
        hata = alinan / (stem + ".error.txt")
        tamam = alinan / (stem + ".txt")
        if hata.exists():
            raise ModelHata("GECICI", "KOPRU: " + hata.read_text(encoding="utf-8", errors="replace")[-300:].replace("\n", " "))
        if tamam.exists():
            raw = tamam.read_text(encoding="utf-8", errors="replace")
            ust, _, cevap = raw.partition("===== ANSWER =====")
            bas = dict(l.split(": ", 1) for l in ust.splitlines() if ": " in l)
            return bas, cevap.strip()
        time.sleep(2)
    raise ModelHata("GECICI", f"KOPRU: {KOPRU_BEKLE_SN // 60} dk içinde cevap gelmedi (Opera/eklenti çalışıyor mu?)")

def _kopru_baglam(self) -> None:
    """Sohbete sistem bağlamını (MIMARI + kod analizi özeti) BİR KERE gönderir; sohbet değişirse yeniden gönderir."""
    durum_yolu = V4 / "logs" / f"kopru_baglam_{self.model}.json"
    try:
        durum = json.loads(durum_yolu.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        durum = {}
    if durum.get("gonderildi") and not self.yeni_baglam_gerek:
        return
    parcalar = []
    for ad, yol in (("MIMARI.md", MIMARI), ("kod_analiz/OZET.md", WORKSPACE / "uxb" / "tekdosyaklsoru" / "kod_analiz" / "OZET.md"),
                    ("kod_analiz/iliski_agi.md", WORKSPACE / "uxb" / "tekdosyaklsoru" / "kod_analiz" / "iliski_agi.md")):
        if yol.exists():
            parcalar.append(f"===== {ad} =====\n{yol.read_text(encoding='utf-8', errors='replace')[:90000]}")
    if not parcalar:
        return
    metin = (GENEL_BAGLAM + "\n\nAşağıda uXBasic derleyicisinin mimari özeti, kod analizi özeti ve ilişki ağı var. "
             "Bu sohbet boyunca sana modül metinleri ve sorular gelecek; bu bağlamı hatırla. Şimdi yalnızca 'TAMAM' yaz.\n\n"
             + "\n\n".join(parcalar))
    bas, _ = self._kopru_gonder(metin, "baglam", "yeni_sohbet=1" if not durum.get("gonderildi") else "")
    durum_yolu.parent.mkdir(parents=True, exist_ok=True)
    durum_yolu.write_text(json.dumps({"gonderildi": True, "zaman": time.strftime("%Y-%m-%dT%H:%M:%S"),
                                      "url": bas.get("PAGE_URL", "")}), encoding="utf-8")
    self.yeni_baglam_gerek = False
    print(f"   [{self.ad}] sistem bağlamı sohbete gönderildi (bir kere): {durum_yolu.name}", flush=True)

yeni_baglam_gerek = False

def _kopru_sor(self, system: str, user: str, schema: dict) -> str:
    self._kopru_baglam()
    sys_full = system + "\nCevabı YALNIZ şu JSON şemasına uyan tek bir JSON nesnesi olarak ver:\n" + json.dumps(schema, ensure_ascii=False)
    bas, cevap = self._kopru_gonder(sys_full + "\n\n" + user, "soru")
    if bas.get("CONTEXT_OK", "True").strip().lower() == "false":
        # sayfa/sohbet değişmiş: bağlamı bir sonraki istekte yeniden gönder
        self.yeni_baglam_gerek = True
        durum_yolu = V4 / "logs" / f"kopru_baglam_{self.model}.json"
        try:
            durum_yolu.unlink()
        except OSError:
            pass
    if not cevap:
        raise ModelHata("GECICI", "KOPRU: boş cevap")
    return cevap

