# ============================================================================
# YEREL KODLAYICI MODEL İÇİN EĞİTİM VERİSİ (-F)
# ============================================================================
# Hedef: qwen2.5-coder gibi yerel modelin uXBasic (.uxb, libsx .bas) yazmayı ve derleyici kaynağını (.fbs) tanımayı öğrenmesi.
# Üç kaynak: (1) gerçek uXBasic programları (tests/docs/game/examples/libsx), (2) kod analizinin rutin kayıtları
# (imza + amaç + gövde), (3) tip/global/karar tablosu amaçları. Çıktı: <hedef>\egitim\{train,valid}.jsonl (sohbet biçimi)
# ve fim_train.jsonl (Qwen FIM biçimi). Bölme dosya adının özetiyle yapılır; aynı dosya hem train hem valid'e girmez.

_EGITIM_KAYNAK_DIZINLERI = ("tests", "docs", "game", "examples", "snippets", "libsx", "xtestx")
_EGITIM_DISLANAN = {"bin", "build", "dist", "out", "reports", "_retired", "backups", "history", ".patch_backup", "Snapshoots",
                    "test_results", "test_results_asm", "node_modules", "__pycache__", ".git"}
_EGITIM_SISTEM = ("Sen uXBasic dilinde uzman bir kodlayıcısın. uXBasic, FreeBASIC'e benzeyen ama kendi kuralları olan bir dildir: "
                  "tipler I8..U64, F32..F128, STRING; LONG/INTEGER/DOUBLE ve $#%! son ekleri YOKTUR; dönüştürme I8(x), U8(x), F32(x) biçimindedir. "
                  "Yalnız çalışan kod yaz.")


def _egitim_calisma_agaci() -> Path:
    return Path(__file__).resolve().parents[4]


def _egitim_bolum(anahtar: str) -> str:
    import hashlib
    return "valid" if int(hashlib.sha1(anahtar.encode("utf-8")).hexdigest()[:6], 16) % 20 == 0 else "train"


def _egitim_oku(yol: Path) -> str:
    try:
        return yol.read_text(encoding="utf-8", errors="replace").replace("\r\n", "\n")
    except OSError:
        return ""


def _egitim_bas_aciklama(metin: str) -> str:
    out = []
    for ln in metin.split("\n")[:25]:
        s = ln.strip()
        if s.startswith("'") or s.lower().startswith("rem "):
            out.append(s.lstrip("'").strip() if s.startswith("'") else s[4:].strip())
        elif s and not out:
            continue
        else:
            break
    return " ".join(x for x in out if x)[:600]


def _egitim_kesim_noktalari(satirlar: List[str]) -> List[int]:
    """Rutin/blok sınırlarında (boş satırdan sonra ve girintisiz satır) güvenli kesim noktaları."""
    cut = []
    for i in range(8, len(satirlar) - 4):
        if not satirlar[i - 1].strip() and satirlar[i].strip() and not satirlar[i][0].isspace():
            cut.append(i)
    return cut


def egitim_verisi_uret(all_files: List[Dict[str, Any]], target_dir: str) -> Dict[str, Any]:
    """Eğitim verisini <target_dir>\\egitim içine yazar. Dönüş: sayılar sözlüğü."""
    import hashlib
    uxbc = _egitim_calisma_agaci()
    uxb = uxbc / "uxb"
    out = Path(target_dir) / "egitim"
    out.mkdir(parents=True, exist_ok=True)
    dosyalar = {"train": (out / "train.jsonl").open("w", encoding="utf-8", newline="\n"),
                "valid": (out / "valid.jsonl").open("w", encoding="utf-8", newline="\n")}
    fim = (out / "fim_train.jsonl").open("w", encoding="utf-8", newline="\n")
    sayac: Counter = Counter()
    gorulen: Set[str] = set()

    def yaz(bolum: str, tur: str, kullanici: str, asistan: str, kaynak: str) -> None:
        if not kullanici.strip() or not asistan.strip():
            return
        kayit = {"messages": [{"role": "system", "content": _EGITIM_SISTEM}, {"role": "user", "content": kullanici},
                              {"role": "assistant", "content": asistan}], "tur": tur, "kaynak": kaynak}
        dosyalar[bolum].write(json.dumps(kayit, ensure_ascii=False) + "\n")
        sayac[f"{bolum}:{tur}"] += 1

    # (1) gerçek uXBasic programları
    adaylar: List[Path] = []
    for d in _EGITIM_KAYNAK_DIZINLERI:
        kok = uxb / d
        if not kok.exists():
            continue
        for p in kok.rglob("*"):
            if p.is_file() and p.suffix.lower() in (".uxb", ".bas") and not (set(p.parts) & _EGITIM_DISLANAN):
                adaylar.append(p)
    for p in sorted(adaylar):
        metin = _egitim_oku(p)
        if len(metin.strip()) < 80 or len(metin) > 60000:
            continue
        h = hashlib.sha1(metin.encode("utf-8")).hexdigest()
        if h in gorulen:                # __dup1 gibi kopyalar tekrar öğretilmesin
            continue
        gorulen.add(h)
        rel = p.relative_to(uxbc).as_posix()
        bolum = _egitim_bolum(rel)
        dil = "uXBasic (.uxb)" if p.suffix.lower() == ".uxb" else "FreeBASIC/uXBasic (.bas)"
        aciklama = _egitim_bas_aciklama(metin)
        if len(metin) <= 12000:
            gorev = aciklama if len(aciklama) >= 20 else f"{p.stem} adlı programı/modülü yaz ({dil})."
            yaz(bolum, "program", f"{dil} ile şunu yapan kod yaz:\n{gorev}", metin, rel)
        satirlar = metin.split("\n")
        kesimler = _egitim_kesim_noktalari(satirlar)
        if kesimler:
            secilen = [kesimler[int(h[i * 4:i * 4 + 4], 16) % len(kesimler)] for i in range(2)]
            for c in sorted(set(secilen)):
                on, son = "\n".join(satirlar[:c]), "\n".join(satirlar[c:])
                if len(on) > 24000:
                    on = on[-24000:]
                yaz(bolum, "devam", f"{dil} kodunun devamını yaz:\n{on}", son[:12000], rel)
            c = secilen[0]
            if bolum == "train":
                fim.write(json.dumps({"text": "<|fim_prefix|>" + "\n".join(satirlar[:c])[-12000:] + "<|fim_suffix|>" +
                                      "\n".join(satirlar[c + 12:])[:6000] + "<|fim_middle|>" + "\n".join(satirlar[c:c + 12]),
                                      "kaynak": rel}, ensure_ascii=False) + "\n")
                sayac["fim"] += 1

    # (2) + (3) kod analizi kayıtları
    veri = Path(target_dir) / "kod_analiz" / "veri"
    kaynak_onbellek: Dict[str, List[str]] = {}

    def satirlar_of(rel: str) -> List[str]:
        if rel not in kaynak_onbellek:
            kaynak_onbellek[rel] = _egitim_oku(uxbc / rel).split("\n")
        return kaynak_onbellek[rel]

    rut_yolu = veri / "rutinler.jsonl"
    if rut_yolu.exists():
        for ln in rut_yolu.open("r", encoding="utf-8", errors="replace"):
            try:
                r = json.loads(ln)
            except ValueError:
                continue
            if r.get("proto") or not r.get("amac") or "belirsiz" in r["amac"].lower()[:40]:
                continue
            satirlar = satirlar_of(r["file"])
            govde = "\n".join(satirlar[r["line"] - 1:r["end_line"]])
            if not (80 <= len(govde) <= 5000):
                continue
            bolum = _egitim_bolum(r["file"])
            ad = (r.get("ns") + "." if r.get("ns") else "") + r["name"]
            ilk = satirlar[r["line"] - 1].strip()
            yaz(bolum, "rutin_yaz", f"Derleyici kaynağında (FreeBASIC) `{ad}` rutinini yaz. Amaç: {r['amac']}\nİmza: {ilk}", govde, r["file"])
            yaz(bolum, "rutin_acikla", f"Bu rutin ne işe yarar?\n{govde}", r["amac"], r["file"])
    for ad, anahtar in (("tipler.jsonl", "tip"), ("globaller.jsonl", "global")):
        yol = veri / ad
        if not yol.exists():
            continue
        for ln in yol.open("r", encoding="utf-8", errors="replace"):
            try:
                r = json.loads(ln)
            except ValueError:
                continue
            if r.get("amac") and r.get("name") and r.get("file"):
                yaz(_egitim_bolum(r["file"]), anahtar, f"uXBasic derleyicisinde `{r['name']}` ({anahtar}, {r['file']}) ne işe yarar?", r["amac"], r["file"])
    for f in (*dosyalar.values(), fim):
