        if kesimler:
            secilen = [kesimler[int(h[i * 4:i * 4 + 4], 16) % len(kesimler)] for i in range(2)]
            for c in sorted(set(secilen)):
                on, son = "\n".join(satirlar[:c]), "\n".join(satirlar[c:])
                if len(on) > 24000:
                    on = on[-24000:]
                yaz(bolum, "devam", f"{dil} kodunun devamını yaz:\n{on}", son[:12000], rel)
            c = secilen[0]
