    kaynak_onbellek: Dict[str, List[str]] = {}

    def satirlar_of(rel: str) -> List[str]:
        if rel not in kaynak_onbellek:
            kaynak_onbellek[rel] = _egitim_oku(uxbc / rel).split("\n")
        return kaynak_onbellek[rel]

    rut_yolu = veri / "rutinler.jsonl"
    if rut_yolu.exists():
        for ln in rut_yolu.open("r", encoding="utf-8", errors="replace"):
            try:
                r = json.loads(ln)
            except ValueError:
                continue
            if r.get("proto") or not r.get("amac") or "belirsiz" in r["amac"].lower()[:40]:
                continue
            satirlar = satirlar_of(r["file"])
            govde = "\n".join(satirlar[r["line"] - 1:r["end_line"]])
            if not (80 <= len(govde) <= 5000):
                continue
            bolum = _egitim_bolum(r["file"])
            ad = (r.get("ns") + "." if r.get("ns") else "") + r["name"]
            ilk = satirlar[r["line"] - 1].strip()
            yaz(bolum, "rutin_yaz", f"Derleyici kaynağında (FreeBASIC) `{ad}` rutinini yaz. Amaç: {r['amac']}\nİmza: {ilk}", govde, r["file"])
            yaz(bolum, "rutin_acikla", f"Bu rutin ne işe yarar?\n{govde}", r["amac"], r["file"])
    for ad, anahtar in (("tipler.jsonl", "tip"), ("globaller.jsonl", "global")):
        yol = veri / ad
        if not yol.exists():
            continue
        for ln in yol.open("r", encoding="utf-8", errors="replace"):
            try:
                r = json.loads(ln)
            except ValueError:
                continue
            if r.get("amac") and r.get("name") and r.get("file"):
                yaz(_egitim_bolum(r["file"]), anahtar, f"uXBasic derleyicisinde `{r['name']}` ({anahtar}, {r['file']}) ne işe yarar?", r["amac"], r["file"])
    for f in (*dosyalar.values(), fim):
        f.close()
    toplam = {k: v for k, v in sorted(sayac.items())}
    (out / "OZET.json").write_text(json.dumps({"zaman": datetime.now().isoformat(timespec="seconds"), "sayilar": toplam,
                                               "uxb_program_dosyasi": len(gorulen)}, ensure_ascii=False, indent=1), encoding="utf-8")
    print(f"-> Eğitim verisi: {out}  {toplam}")
    return {"durum": "tamam", "sayilar": toplam}


