$f="C:\Users\mete\Downloads\BasicOyunSource\UXBc_Clean\UXBc\mete_prompt_bridge_mvp\extension\content.js"
$c=Get-Content $f -Raw -Encoding utf8
$i=$c.IndexOf('  let ok = false;')
$j=$c.IndexOf('async function clickSend')
$yeni=@'
  // 1) yapistirma olayi (ProseMirror/Quill kendi isler). Sonucu DONUS DEGERINE degil, KUTUNUN ICERIGINE bakarak anla:
  //    editor olayi iptal etmeden de ekleyebilir; eskiden bu durumda ikinci yontem metni bir kez daha yazip metni ikiye katliyordu.
  const yazildi = () => (el.innerText || el.textContent || "").replace(/\s+/g, "").length >= value.replace(/\s+/g, "").slice(0, 200).length;
  try {
    const dt = new DataTransfer();
    dt.setData("text/plain", value);
    el.dispatchEvent(new ClipboardEvent("paste", { clipboardData: dt, bubbles: true, cancelable: true }));
  } catch (_) {}
  // 2) yazilmadiysa execCommand
  if (!yazildi()) document.execCommand("insertText", false, value);
  // 3) hala bos ise dogrudan metin
  if (!yazildi()) {
    el.textContent = value;
    el.dispatchEvent(new InputEvent("input", { bubbles: true, inputType: "insertText", data: value }));
  }
}


'@
