# -*- coding: utf-8 -*-
f = r"C:\Users\mete\Downloads\BasicOyunSource\UXBc_Clean\UXBc\UxbRAG\UXB_HYBRID_RAG_V4_YORUMLU_JSON\tools\Moduller\RAGVeriHazirlayici.py"
t = open(f, encoding="utf-8").read()

yeni_fonksiyonlar = r'''
# ---------------------------------------------------------------------------
# DİL KARTLARI: her anahtar sözcük / yerleşik ad / kütüphane işlevi için KANITTAN beslenen eğitim örnekleri
# ---------------------------------------------------------------------------
# Kanıt kaynakları: (1) src/surface kayıt tabloları (grup/tür), (2) docs/kitaplar/_ortak/dil_yuzeyi.json (hangi katman/motor
# uyguluyor, kaç test programı kullanıyor), (3) hedef tasarım kılavuzundaki kod blokları (sözdizimi biçimleri), (4) çalıştırılıp
# DOĞRULANMIŞ örnekler (ornek_dogrula sonuçları, 3 motorda geçen), (5) tests/ altındaki gerçek program parçaları, (6) libsx
# kütüphane işlevlerinin kod analizi kayıtları (imza + amaç). Uydurma metin yoktur; kanıt yoksa kart yazılmaz.

_KILAVUZ = "docs/tasarim/uXBasic_Hedeflenen_Sistem_ve_Kullanma_Kilavuzu_TR_2026-09-24 (1).md"


def _dk_kayit_tablolari(uxb: Path) -> Dict[str, Dict[str, str]]:
    kayit = _egitim_oku(uxb / "src" / "surface" / "uxb_surface_registry.fbs").split("\n")

    def govde(ad):
        try:
            bas = next(i for i, l in enumerate(kayit) if re.match(rf"\s*Function {ad}\b", l))
            son = next(i for i in range(bas + 1, len(kayit)) if re.match(r"\s*End Function", kayit[i]))
        except StopIteration:
            return []
        return kayit[bas:son]

    def sozluk(satirlar):
        d = {}
        for i, l in enumerate(satirlar):
            m = re.match(r'\s*Case\s+(.+?)\s*:\s*Return\s+(.+?)\s*$', l)
            if m:
                for k in re.findall(r'"([^"]*)"', m.group(1)):
                    d[k] = m.group(2).strip().strip('"')
                continue
            m = re.match(r'\s*Case\s+(.+?)\s*$', l)
            if m and '"' in m.group(1) and i + 1 < len(satirlar):
                mm = re.match(r"\s*Return\s+(.+)", satirlar[i + 1])
                for k in re.findall(r'"([^"]*)"', m.group(1)):
                    d[k] = mm.group(1).strip().strip('"') if mm else ""
        return d

    return {"grup": sozluk(govde("UXBSurfaceGroup")), "tur": sozluk(govde("UXBSurfaceKind")), "bilinen": sozluk(govde("UXBSurfaceKnown"))}


def _dk_kilavuz_bloklari(uxbc: Path) -> Dict[str, List[str]]:
    """Kılavuzdaki kod bloklarından: sözcük -> o sözcüğü içeren satırlar (sözdizimi biçimleri, en çok 8)."""
    metin = _egitim_oku(uxbc / "uxb" / _KILAVUZ)
    out: Dict[str, List[str]] = defaultdict(list)
    for blok in re.findall(r"```(?:basic|text|uxb)?\n(.*?)```", metin, re.S):
        for ln in blok.split("\n"):
            s = ln.strip()
            if not s or s.startswith("'"):
                continue
            for w in set(re.findall(r"\b[A-Za-z_][A-Za-z0-9_]*\b", s)):
                if len(out[w.upper()]) < 8 and s not in out[w.upper()]:
                    out[w.upper()].append(s)
    return out


def _dk_dogrulanmis_ornekler(uxb: Path) -> Dict[str, List[Dict[str, Any]]]:
    """Üç motorda GEÇEN ve beklenen çıktısı olan örnekler; sözcük -> örnek listesi."""
    yol = None
    for ad in ("ornek_sonuclari_20261007.json", "ornek_sonuclari.json"):
        p = uxb / "docs" / "kitaplar" / "_ortak" / ad
        if p.exists():
            yol = p
            break
    out: Dict[str, List[Dict[str, Any]]] = defaultdict(list)
    if not yol:
        return out
    try:
        veri = json.loads(yol.read_text(encoding="utf-8"))
    except ValueError:
        return out
    for r in veri:
        if not r.get("hepsi") or not r.get("beklenen"):
            continue
        p = uxb / r["dosya"]
        kod = _egitim_oku(p)
        govde = "\n".join(l for l in kod.split("\n") if not l.startswith(("' KONU", "' KOMUTLAR", "' ACIKLAMA", "'=")))
        if not govde.strip():
            continue
        kayit = {"dosya": r["dosya"], "kod": govde.strip(), "cikti": "\n".join(r["beklenen"]), "konu": r.get("konu", ""), "aciklama": r.get("aciklama", "")}
        sozler = set(w.upper() for w in r.get("komutlar") or [])
        sozler |= set(w.upper() for w in re.findall(r"\b[A-Za-z_][A-Za-z0-9_]*\b", govde))
        for w in sozler:
            out[w].append(kayit)
    return out


def _dk_test_parcalari(uxb: Path) -> Dict[str, List[str]]:
    """tests/ altındaki küçük gerçek programlar: sözcük -> (en çok 2) program metni."""
    tersine: Dict[str, List[Tuple[int, str]]] = defaultdict(list)
    for p in sorted((uxb / "tests").rglob("*.uxb")):
        if set(p.parts) & _EGITIM_DISLANAN:
            continue
        kod = _egitim_oku(p)
        if not (60 <= len(kod) <= 1500):
            continue
        for w in set(re.findall(r"\b[A-Za-z_][A-Za-z0-9_]*\b", "\n".join(l for l in kod.split("\n") if not l.strip().startswith("'")))):
            tersine[w.upper()].append((len(kod), kod))
    out = {}
    for w, liste in tersine.items():
        liste.sort()
        gorulen, secilen = set(), []
        for _, kod in liste:
            if kod not in gorulen:
                gorulen.add(kod)
                secilen.append(kod)
            if len(secilen) == 2:
                break
        out[w] = secilen
    return out


def dil_kartlari_ekle(yaz, uxbc: Path, uxb: Path, kod_analiz_veri: Path, sayac) -> None:
    """Anahtar sözcük, yerleşik ad ve kütüphane işlevi kartlarını eğitim örneği olarak yazar."""
    yuzey_yolu = uxb / "docs" / "kitaplar" / "_ortak" / "dil_yuzeyi.json"
    if not yuzey_yolu.exists():
        return
    yuzey = json.loads(yuzey_yolu.read_text(encoding="utf-8"))
    tablo = _dk_kayit_tablolari(uxb)
    kilavuz = _dk_kilavuz_bloklari(uxbc)
    dogru = _dk_dogrulanmis_ornekler(uxb)
    testler = _dk_test_parcalari(uxb)
    motor_adi = {"ast_yorum": "AST yorumlayıcı", "mir_yorum": "MIR yorumlayıcı", "native_x64": "native x64", "legacy_x64": "legacy x64", "js": "JS", "wasm": "WASM"}

    for r in yuzey:
        if r.get("sinif") not in ("anahtar", "yerlesik"):
            continue
        ad = r["ad"]
        if not re.match(r"^[A-Za-z_][A-Za-z0-9_]*$", ad):
            continue
        kat = r.get("katmanlar") or {}
        bolum = _egitim_bolum("dil:" + ad)
        # KURAL: ölü adlar (LONG/INTEGER/DOUBLE ...) dilin parçası değildir; bunları öğretme
        if ad.upper() in ("LONG", "INTEGER", "DOUBLE", "SINGLE", "BYTE"):
            yaz(bolum, "dil_yasak", f"uXBasic'te `{ad}` tip adı kullanılır mı?",
                f"Hayır. uXBasic'te `{ad}` diye bir tip adı yoktur (LONG/INTEGER/DOUBLE/SINGLE/BYTE ve $ # % ! & tip son ekleri dilde YOKTUR). "
                "Tipler I8 U8 I16 U16 I32 U32 I64 U64 F32 F64 F80 F128 BOOLEAN STRING biçimindedir; dönüştürme I32(x), F32(x) gibi tip adıyla yapılır.", "YONERGE §2")
            continue
        satirlar = []
        sinif_ad = "anahtar sözcük" if r["sinif"] == "anahtar" else "yerleşik ad (fonksiyon/yordam)"
        satirlar.append(f"`{ad}` uXBasic'te bir {sinif_ad}tür.")
        g, tr = tablo["grup"].get(ad), tablo["tur"].get(ad)
        if g or tr:
            satirlar.append("Yüzey kaydındaki sınıfı: " + ", ".join(x for x in (f"grup {g}" if g else "", f"tür {tr}" if tr else "") if x) + ".")
        uyg = [motor_adi[k] for k in ("ast_yorum", "mir_yorum", "native_x64", "legacy_x64", "js", "wasm") if k in kat]
        eksik = [motor_adi[k] for k in ("ast_yorum", "mir_yorum", "native_x64", "js", "wasm") if k not in kat]
        if uyg:
            satirlar.append("Kaynakta şu katmanlarda işlenir: " + ", ".join(uyg) + (f". Kaynakta anılmayan: {', '.join(eksik)}." if eksik else "."))
        elif kat:
            satirlar.append("Kaynakta yalnız ön yüz katmanlarında (" + ", ".join(sorted(kat)) + ") geçer; motor katmanlarında adıyla anılmıyor.")
        if r.get("uxb_dosya"):
            satirlar.append(f"Test/örnek kod tabanında {r['uxb_dosya']} .uxb programında kullanılıyor.")
        bicim = kilavuz.get(ad.upper(), [])
        if bicim:
            satirlar.append("Tasarım kılavuzundaki yazım biçimleri:\n" + "\n".join("    " + b for b in bicim[:6]))
        dg = dogru.get(ad.upper(), [])
        dg = sorted(dg, key=lambda e: len(e["kod"]))[:1]
        if len(satirlar) >= 2:
            yaz(bolum, "dil_kart", f"uXBasic'te `{ad}` nedir, nasıl yazılır ve hangi motorlarda çalışır?", "\n".join(satirlar), "dil_yuzeyi+kayit+kilavuz")
        for e in dg:
            yaz(bolum, "dil_ornek", f"uXBasic'te `{ad}` kullanan çalışan bir örnek yaz. Beklenen çıktıyı da söyle.",
                f"```basic\n{e['kod']}\n```\nÇıktı (AST, MIR ve native x64'te doğrulandı):\n{e['cikti']}", e["dosya"])
        if not dg:
            for kod in testler.get(ad.upper(), [])[:1]:
                yaz(bolum, "dil_ornek", f"uXBasic'te `{ad}` kullanan gerçek bir test programı göster.", f"```basic\n{kod.strip()}\n```", "tests")

    # kütüphane işlevleri: libsx kod analizi kayıtları (imza + amaç + ad alanı) + testlerden çağrı satırı
    rut_yolu = kod_analiz_veri / "rutinler.jsonl"
    if rut_yolu.exists():
        cagri_satirlari: Dict[str, str] = {}
        for p in sorted((uxb / "tests").rglob("*.uxb")):
            if set(p.parts) & _EGITIM_DISLANAN:
                continue
            for ln in _egitim_oku(p).split("\n"):
                for m in re.finditer(r"\b([A-Za-z_][A-Za-z0-9_]*)\.([A-Za-z_][A-Za-z0-9_]*)\s*\(", ln):
                    cagri_satirlari.setdefault((m.group(1) + "." + m.group(2)).upper(), ln.strip())
        for ln in rut_yolu.open("r", encoding="utf-8", errors="replace"):
            try:
                r = json.loads(ln)
            except ValueError:
                continue
            if r.get("proto") or not r["file"].startswith("uxb/libsx/") or not r.get("amac") or not r.get("name"):
                continue
            ns = r.get("ns") or ""
            tam = (ns + "." if ns else "") + r["name"]
            kutup = r["file"].split("/")[2] if r["file"].count("/") >= 3 else r["file"]
            ilk = _egitim_oku(uxbc / r["file"]).split("\n")[r["line"] - 1].strip()
            cevap = [f"`{tam}` uXBasic kütüphane işlevidir ({kutup} kütüphanesi).", f"İmza: {ilk}", f"Amaç: {r['amac']}"]
            cl = cagri_satirlari.get(tam.upper())
            if cl:
                cevap.append("Testlerden gerçek bir çağrı: `" + cl + "`")
            yaz(_egitim_bolum(r["file"] + ":" + r["name"]), "kutuphane_islev", f"uXBasic'te `{tam}` ne yapar, imzası nedir?", "\n".join(cevap), r["file"])
'''

# 1) fonksiyonları egitim_verisi_uret'ten önce ekle
t = t.replace("def egitim_verisi_uret(all_files", yeni_fonksiyonlar + "\n\ndef egitim_verisi_uret(all_files", 1)
# 2) gerekli içe aktarmalar
t = t.replace("from collections import defaultdict, Counter", "from collections import defaultdict, Counter", 1)
# 3) çağrı: kapanıştan önce
t = t.replace("    for f in (*dosyalar.values(), fim):\n        f.close()",
              "    dil_kartlari_ekle(yaz, uxbc, uxb, veri, sayac)\n    for f in (*dosyalar.values(), fim):\n        f.close()", 1)
open(f, "w", encoding="utf-8", newline="").write(t)
print("ok", "dil_kartlari_ekle" in t)

